(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["br"] = {"ui":{"skip":"Mont d'an endalc'hadoù","back":"← Distro da AI-gile","lang.button":"Yezh: {name}","lang.dialog":"Dibab ur yezh","lang.search":"Klask yezhoù","lang.none":"Yezh ebet ne glot","lang.notYet":"{name} n'eo ket bet treset c'hoazh","theme.aria":"Cheñch tem: sklaer, teñval pe du","theme.toLight":"Cheñch d'an tem sklaer","theme.toDark":"Cheñch d'an tem teñval","theme.toBlack":"Cheñch d'an tem du (du gwirion, flour evit ar skrammoù OLED)","words.underline":"Islinennañ ar gerioù-mañ war ar bajenn","words.underlineHelp":"Lakait al logodenn war ur ger pikennaouet pe stokit anezhañ evit gwelet petra eo e ster.","words.col.todo":"Kartennoù dibabet evit bremañ: ar skipailh a grog gant ar re-mañ da heul.","words.col.doing":"Un AI a labour war ar gartenn-mañ bremañ.","words.col.review":"Un AI en deus echuet al labour; unan all a wiriañ anezhañ a-raok ma teuio d'ac'h.","words.col.verify":"O c'hortoz ac'hanoc'h: esaeit anezhañ ha lavarit deomp hag-eñ e ya mat.","words.col.team":"Ho notennoù pe ho respontoù, o c'hortoz ma vo kemeret gant ar skipailh.","words.col.done":"Echu ha degemeret.","index.title":"AI-gile: ho skipailh diorren AI, war un daolenn","index.description":"AI-gile zo un daolenn kanban evit skipailhoù AI a god. Labourat a reont p'emaoc'h o kousket; ur bern berr traoù da zivizout, da amprouiñ ha da asantiñ a vo evidoc'h.","hero.logoAlt":"Arlun taolenn AI-gile","hero.h1.html":"Ho skipailh diorren AI, war un&nbsp;daolenn.","hero.alpha":"🐣 Pre-alfa serret","hero.alphaTitle":"Abred ha n'eo ket echu: trugarez da glask anezhañ!","hero.lede":"Savet e vez ganto p'emaoc'h o kousket. Dihunet e vefec'h gant ur bern berr: un nebeut goulennoù, un nebeut traoù da amprouiñ, un diamant mouk pe zaou. Klik, asantet, distro d'ho kafe.","dl.windows":"Arload Windows","dl.browser":"Lañsañ en ho merdeer","dl.messenger":"📱 Messenger evit ho pellgomz","dl.soon":"Dont a ra abred","dl.notify":"🔔 Lavarit din p'en em zigor","dl.notifySmall":"Alfa pe beta","hero.secondary":"Agile, met ar skipailh n'en deus ket ezhomm eus ur c'hafe stand-up morse. (Stand-up a reont koulskoude.)","pitch.h2":"AI-gile e kement a c'her ha ma karot","pitch.lede":"Dibabit ul hirder, diwar ur ger betek 144. Pep hirder zo ur zeskrivadenn, skrivet evit ar vent-se. Riklit ar riklenn pe implijit an alc'hwezioù-saeta.","pitch.rangeLabel":"Hirder e gerioù","pitch.dice":"🎲 ur stumm all","pitch.words.one":"{n} ger","pitch.words.other":"{n} ger","pitch.letters.one":"{n} lizherenn","pitch.letters.other":"{n} lizherenn","pitch.chars.one":"{n} arouez","pitch.chars.other":"{n} arouez","count.line.html.one":"{n} kartenn war an daolenn bremañ","count.line.html.other":"{n} kartenn war an daolenn bremañ","people.humans.html.one":"👥 {n} den","people.humans.html.other":"👥 {n} den","people.agents.html.one":"🤖 {n} ajant","people.agents.html.other":"🤖 {n} ajant","people.working.html.one":"⚡ {n} o labourat bremañ","people.working.html.other":"⚡ {n} o labourat bremañ","pre.title":"AI-gile: un dra bennak a zo o vezañ savet","pre.description":"Un dra bennak a zo o vezañ savet amañ. Un daolenn ma sav skipailhoù AI ar pezh a c'houlennit, en ur zeskiñ deoc'h a-hed an hent. Evit ar mare, ur pre-alfa serret gant mignoned.","pre.h1":"Un dra bennak a zo o vezañ savet amañ. 🤫","pre.line":"Un daolenn ma sav skipailhoù AI ar pezh a c'houlennit, en ur zeskiñ deoc'h a-hed an hent. Evit ar mare, ur pre-alfa serret gant mignoned.","pre.btn":"🔔 Lavarit din p'en em zigor","pre.peek":"A-dreñv ar werenn: an daolenn wir, war-eeun. Pep kartenn a zo ur varrenn liv.","pre.peekFake":"A-dreñv ar werenn: setu penaos e seblant un daolenn o labourat.","pre.night":"🌙 Gward an noz a zo e karg · 😴 an den a zo o repoz","features.aria":"Ar pezh a ra","f.pile.h":"Ur bern evidoc'h","f.pile.html":"<b>Evidoc'h</b> a dastum pep tra a c'hortoz ac'hanoc'h, dre an holl raktresoù: goulennoù, traoù da amprouiñ, labourioù n'hall ober nemet un den. Ho renkad a lavar petra zo da heul ha pet pad a ra.","f.sleep.h":"Skipailhoù a labour p'emaoc'h o kousket","f.sleep.p":"Pep raktres en deus ur penn-skipailh hag ur skipailh ajanted AI. Skrivit un evezhiadenn war ur gartenn ha dihuniñ a ra ar skipailh, ober a ra al labour hag e kas en-dro deoc'h gant pazennoù a c'hall heuliañ un den skuizh.","f.tester.h":"Un amprouer AI a wiriekaat da gentañ","f.tester.p":"Kent ma'z afe tra ebet betek ac'hanoc'h, un amprouer a heul ar pazennoù en un eilad eus an arload hag a ziskouez ar pezh en deus gwelet, gant ur skeudenn skramm. Lenit buan ar re a zo aet mat hag asantit ho klik.","f.proof.h":"Pruvoù, n'eo ket promesaoù","f.proof.p":"Pep treuzkas a ziskouez ar pezh zo cheñchet: ar restroù, an diforc'hioù, ar skeudennoù skramm. Dre ret n'eo ket digeriñ pep arload evit gouzout hag-eñ eo echu.","f.chat.h":"Flapañ gant ho pennoù-skipailh","f.chat.p":"Ur varrenn evel Discord: un arlun dre raktres, diamantoù mouk evit ar pezh en deus ezhomm ac'hanoc'h. Kasit ur mennozh d'ur penn-skipailh; e kartennoù hag e blan e troio, gant ur bouton ✅ Go.","f.tidy.h":"Mirout urzh en-unan","f.tidy.p":"Ar c'hartennoù kar a vez kenstrollet en unan, an titloù mesk a vez reizhet, ha gwiriañ an tokenoù a vir ar c'hod skañv. Nebeutoc'h a draoù da cheñch etrezo, nebeutoc'h da soñjal.","f.private.h":"Ho re, war hoc'h urzhiater","f.private.li1":"An daolenn a red war ho jestr deoc'h-c'hwi hag a respont deoc'h hepken.","f.private.li2":"Ar c'hemennadennoù prevez etre tud a zo sifret penn-da-benn.","f.private.li3":"Kont ebet, heulier ebet, koukiz ebet.","f.lang.h":"En ho yezh","f.lang.p":"Ouzhpenn 120 yezh, eus an nederlandeg, ar c'hembraeg hag ar japoneg betek ar pirat, Yoda ha klingon, gant ur cheñchamant buan en-dro d'ar saozneg evit gerioù ar vicher.","f.service.h":"Eus ur soñj d'ur gwir servij","f.service.p":"Savet ho peus gant an IA un dra a implij an dud bremañ? Merkit anezhañ evel ur servij hag an daolenn a sikour ac'hanoc'h d'e lakaat da vont en-dro mat: gwiriadennoù pad-labour, ur bajenn statud foran, darvoudoù gant un dielfennadenn, cheñchamantoù a c'houlenn ur Mont, eilennoù surentez gwiriet bemdez. Ar Sikour a zesk deoc'h pep pazenn a-hed an hent.","msgr.h2":"AI-gile Messenger: ho skipailh en ho poc'hed","msgr.p1":"Komzit gant ho skipailh AI hep digeriñ ar bord. Flapit gant ho pennoù-raktres hag ho mignoned, gwelit pazennoù-test ur gartenn ha respontit dezho, an holl diouzh ho pellgomz.","msgr.p2":"Evit e liammañ, skanit ur c'hod QR war ho pord. Ar wech kentañ? Ur flap demo mignon a ziskouezo deoc'h an traoù.","msgr.when":"Android da gentañ, goude ur stumm web evit ar pellgomzoù hag an iPhone.","msgr.who":"Ho penn-raktres","msgr.b1":"Prest eo reizhadenn ar mod teñval. Fellout a ra deoc'h ar pazennoù-test?","msgr.b2":"Ya, mar plij!","msgr.b3":"1. Digorit Arventennoù. 2. Dibabit Teñval. Mat eo an neuz?","tl.aria":"Amzeriadur eus ar c'hentañ kaozeadenn betek ar gevrenn-hent","tl.h2":"Eus ar c'hentañ flap d'ar pezh zo da heul","tl.lede":"Deizioù hag eurioù gwir, en ho takad eur deoc'h-c'hwi. Goude hiziv eo ar plan, hep deiziad ebet prometet.","tl.today":"Hiziv","tl.planned":"bet raktreset","tl.doing":"e-kerzh","tl.cards.one":"{n} kartenn","tl.cards.other":"{n} kartenn","join.h2":"Deuit ganeomp","join.lede":"AI-gile a vez savet gant ur paotr barvek iskis, gant AuDHD hag un nebeud emgannoù gant ar yec'hed-bred, hag un niver bras a ajanted habask. Prevez eo evit bremañ, en un alfa serret gant mignoned. C'hoant hoc'h eus d'e amprouiñ p'en em zigoro?","join.btn":"Lavarout ho c'hoant","join.small":"Skrivañ a raimp deoc'h dre bostel, netra all","footer.tag":"AI-gile. Heulier ebet, koukiz ebet, kafe stand-up ebet.","footer.licence":"Aotre embregerezh","footer.status":"Stad","footer.privacy":"Ar pezh a viromp","footer.thanks":"Galvoù a-drugarez da ChilledChat","form.sending":"O kas…","form.failed":"N'eo ket aet en-dro: klaskit en-dro diwezhatoc'h.","form.offline":"N'eus ket tu da dizhout AI-gile: klaskit en-dro diwezhatoc'h.","form.keep":"Ne implijomp an dra-se nemet evit respont deoc'h, ha goude e lamomp anezhañ. Heulier ebet, koukiz ebet.","form.keepLink":"Ar pezh a viromp","interest.title":"AI-gile: lavarit din p'en em zigoro an alfa","interest.description":"Leuskit ho postel evit gouzout p'en em zigoro alfa serret pe beta AI-gile.","interest.h1":"🔔 Lavarit din p'en em zigor","interest.lede":"AI-gile zo e pre-alfa serret. Leuskit ho postel hag e skrivimp deoc'h unwezh, p'en do un plas evidoc'h.","interest.email":"Ho postel","interest.which":"Peseurt amprouadenn?","interest.alpha":"Alfa serret: abred, garv, kalz cheñchamantoù","interest.beta":"Beta: stabiloc'h, diwezhatoc'h","interest.both":"An eil pe egile, an hini a zeu da gentañ","interest.submit":"Lakait ac'hanon war ar roll","interest.thanks":"Trugarez! War ar roll oc'h.","licence.title":"AI-gile: aotre embregerezh","licence.description":"Implijout a rit AI-gile en ho embregerezh? Goulennit un aotre embregerezh digoust.","licence.h1":"📜 Aotre embregerezh","licence.lede":"Implijout a rit AI-gile er labour? Lavarit deomp piv oc'h hag petra a rit. M'ober a ra un tammig mat, digoust eo an aotre.","licence.company":"Embregerezh","licence.website":"Lec'hienn","licence.what":"Ar pezh a rit","licence.how":"Penaos e sikour ar bed","licence.email":"Postel","licence.submit":"Goulenn","licence.thanks":"Trugarez! Respont a raimp dre bostel.","status.title":"Stad AI-gile","status.h1":"Stad AI-gile","status.quiet":"Peoc'h an holl","status.intro":"Ha mont a ra AI-gile en-dro bremañ? Ar bajenn-mañ a wiri al lec'hienn, rannañ an taolennoù, ar galvoù hag ar pellgargañ bep 5 munutenn.","status.up":"Mont a ra en-dro (respontet e {ms} ms)","status.slow":"N'en deus ket respontet d'ar wiriadenn ziwezhañ, o klask en-dro","status.down":"Paouezet: n'en deus ket respontet d'an div wiriadenn ziwezhañ","status.svc.web":"Lec'hienn","status.svc.web.offers":"Al lec'hienn-mañ: petra eo AI-gile, hag ar furmskrid dedenn","status.svc.boards":"Rannañ an taolennoù","status.svc.boards.offers":"Taolennoù foran, kemennadennoù etre mignoned ha pedadennoù","status.svc.calls":"Galvoù","status.svc.calls.offers":"Mouezh, video ha rannañ skramm en AI-gile","status.svc.download":"Pellgargañ","status.svc.download.offers":"Ar stalier Windows hag al liammoù pediñ","status.checking":"O wiriañ…","status.offline":"N'eus ket tu da dizhout ar servij stad bremañ (o klask en-dro)","status.updated":"hizivaet {ago}","status.justNow":"bremañ just","status.min":"{n} min zo","status.hours":"{n} h zo","status.days":"{n} d zo","privacy.title":"AI-gile: ar pezh a viromp","privacy.h1":"Ar pezh a viromp","privacy.lede":"E berr gomzoù: ar pezh a gasit deomp hepken, ha n'eo ket evit pell.","privacy.only":"Ar pezh a gasit deomp hepken: ar pezh a skrivit en ur furmskrid, evel ho postel. Netra all diwar ho penn.","privacy.sealed":"Siellet eo evit na c'hallfe ket hor servijer e lenn: en ho merdeer a-raok ma'z a kuit (war ur merdeer koshoc'h, kerkent ha ma tegouezh). Hon taolenn hon-unan hepken a c'hall e zigeriñ.","privacy.server":"Lamet e vez diwar ar servijer kerkent ha ma tizh hon taolenn. Kement tra a chomfe eno goude 30 devezh a vez lamet memes tra.","privacy.board":"Ne viromp anezhañ war hon taolenn nemet betek ma vo bet respontet deoc'h, ha goude e lamomp anezhañ eno ivez.","privacy.none":"Heulier ebet, koukiz ebet, dielfennañ ebet.","privacy.local":"Ho yezh hag ho tibab sklaer pe teñval a chom en ho merdeer deoc'h-c'hwi. Ne vezont morse kaset deomp.","privacy.ask":"C'hoant hoc'h eus e vefe lamet abretoc'h? Respontit d'hor postel ha lavarit deomp.","live.h2":"Sellit ouzh e vezañ savet, war-eeun","live.caption":"Pep kartenn a zo kuzhet: gwelout a rit stumm al labour, ket ar gerioù.","live.watching.one":"war-eeun: {n} o sellout","live.watching.other":"war-eeun: {n} o sellout","live.last.now":"Ar gartenn ziwezhañ a zo bet dilec'hiet bremañ","live.last.min.one":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} min zo","live.last.min.other":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} min zo","live.last.hour.one":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} eur zo","live.last.hour.other":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} eur zo","live.last.day.one":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} deiz zo","live.last.day.other":"Ar gartenn ziwezhañ a zo bet dilec'hiet {n} devezh zo","live.offline":"Ur pennad diskuizh a gemer an daolenn war-eeun. Distroit a-benn nebeut.","live.cols":"Backlog|Da ober|O vont war-raok|Ar skipailh a wiriañ|Evidoc'h da test|Evit ar skipailh|Graet","footer.models":"AI-gile a lañs skouerioù AI evidoc'h. Ar pezh a lavaront hag a ront zo o dra-i, setu gwiriekait a-raok fiziañs.","privacy.ai.h":"Al lodenn AI","privacy.ai.models":"AI-gile eo ar bord. Skouerioù AI a gompagnunezhioù all, evel Claude, Codex ha Gemini, a ra al labour war ho kontoù deoc'h-c'hwi.","privacy.ai.check":"Ar pezh a skrivont hag a ront a zeu diwarno hag a c'hall bezañ fall. Gwiriekait a-raok bezañ fiziet enno pe embann.","privacy.ai.files":"Cheñch a reont restroù ha lañsañ a reont urzhioù er c'havlec'hioù a gevrit. Likit un eilad-wareziñ.","privacy.ai.send":"Ar pezh a roit d'ur skouer a ya d'ar gompagnunezh a lañs anezhañ, hervez o c'honditionoù. Tizhout a ra kondisionoù ha koustoù pep hini.","privacy.ai.asis":"AI-gile zo ur stumm esae kentañ, roet evel m'emañ."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotoù.","Dilezet."]},{"n":2,"texts":["Kanban robotoù.","Ajanted urzhiet.","Mennozhioù, savet."]},{"n":3,"texts":["Kanban evit robotoù.","Mennozhioù da perzhioù.","Kanban ajanted digoust."]},{"n":5,"texts":["Taolenn kanban rediet gant ajanted.","C'hwi a skriv. Ajanted a sav.","Digoust, lec'hel, amprouet, un tammig sot."]},{"n":8,"texts":["Taolenn kanban digoust, ajanted AI a labour warni.","Skrivit ur mennozh. Ajanted a sav anezhañ. Asantit.","Agile evit un den hag kalz robotoù a-bouez."]},{"n":13,"texts":["Un daolenn kanban war hoc'h urzhiater e vez kemeret ar c'hartennoù gant ajanted AI.","Skrivit ur mennozh. Ur skipailh ajanted a sav anezhañ. Un amprouer a wiriekaat.","Digoust, kont ebet, heulier ebet: un daolenn, un nebeut robotoù, hag c'hwi a gomz."]},{"n":21,"texts":["AI-gile zo un daolenn kanban evit labourat gant ajanted AI a god. Kemer a reont ar c'hartennoù; c'hwi a amprouf hag a asant anezho.","Pep raktres en deus ur penn-skipailh hag ur skipailh ajanted AI. Skrivit un evezhiadenn war ur gartenn ha krog a ra ar skipailh.","Un daolenn labourioù personel ha digoust a red war hoc'h urzhiater deoc'h-c'hwi. Robotoù eo al labourerien. An hini a lavar ya eo c'hwi."]},{"n":34,"texts":["Lakaat a rit mennozhioù war un daolenn. Ur skipailh ajanted AI a laka anezho da perzhioù o labourat, a amprouf anezho, hag a gas en-dro anezho deoc'h gant pazennoù da amprouiñ. Tra ebet n'eo echu a-raok ma lavarit.","AI-gile zo un daolenn kanban graet er gêr gant Rich, gant kalz skoazell eus an ajanted a gas bremañ. Digoust eo, a red war hoc'h urzhiater, hag a vez rannet gant mignoned, n'eo ket gwerzhet.","Soñjit en un daolenn kanban boas, gant bannoù eus ar Backlog betek Graet, nemet ar c'hartennoù a vez kemeret gant ajanted AI. Displegañ a reont o araokadenn, goulenn m'int stag, ha gortoz atav ho tudenn war-laez."]},{"n":55,"texts":["AI-gile zo un daolenn kanban m'eo ajanted AI ar skipailh. Pep raktres en deus ur penn-skipailh a blan al labour ha skoazelloù a sav anezhañ. Pa vez prest ur perzh, un amprouer AI a amprouf anezhañ hag a ra ur skeudenn skramm, goude-se e teu en ho pern. Asantit anezhañ, pe skrivit un evezhiadenn hag e adober a raint.","Krog eo bet evel un doare evit un den da heuliañ kalz estrenvaoù kodiñ AI war un dro, ha kresket eo e daolenn wirion. Ober a ra war ho jestr, n'en deus ket ezhomm eus kont, ha n'en deus heulier ebet. Digoust eo evit mignoned ha re c'hoant-gouzout. N'eo ket echu c'hoazh, setu gortozit riblennoù garv hag un souezh a-wechoù.","Setu ar stumm onest. Ret eo deoc'h kaout ar mennozhioù c'hoazh, ha gwiriañ an disoc'hoù c'hoazh. Ar pezh a ra AI-gile eo pep tra etre an daou: miret a ra ar c'hartennoù en urzh, dihuniñ a ra an ajant mat pa skrivit un evezhiadenn, diskouez a ra egzakt ar pezh zo cheñchet, ha lakaat a ra an holl en ur bern berr evidoc'h."]},{"n":89,"texts":["AI-gile zo un daolenn kanban digoust a lañsit war hoc'h urzhiater deoc'h-c'hwi. En tu all d'an dud, pep raktres en deus ur skipailh ajanted AI: ur penn-skipailh a laka ho mennozhioù da gartennoù ha da blan, ha skoazelloù a gemer ar c'hartennoù hervez o raktres. Pa vez savet un dra bennak, un amprouer AI a heul ar pazennoù amprouiñ hag a ziskouez deoc'h ar pezh en deus gwelet. Goude-se e c'hortoz en ur bern anvet Evidoc'h. Asantiñ a rit, pe skrivit un evezhiadenn hag ar skipailh a glask en-dro. Tra ebet ne zeu da Graet hep c'hwi.","Un nebeut traoù na c'hortozit ket marteze. Ur gward-noz a vir ar bann Da ober leun p'emaoc'h o kousket, o tibab kartennoù na c'houlennont ket respont diganeoc'h. Ur jedour tokenoù a ziskouez pet en deus implijet an ajanted hiziv hag ar sizhun-mañ, ha No Token Mode a lavar dezho paouez da zispign. Gallout a rit skrivañ da vignoned, ha sifret eo ar c'hemennadennoù prevez penn-da-benn. An daolenn a gomz tro-dro 120 yezh, en o zouez nederlandeg, flamanteg, pirat ha klingon. Netra eus se ne gousto ur gwenneg, ha den n'eo o klask gwerzhañ se deoc'h.","AI-gile zo ur raktres bihan, personel, n'eo ket un embregerezh. C'hoant en doa Rich da ober war-dro meur a raktres kodiñ AI hep digeriñ pep arload evit o gwiriañ, setu en deus savet gant an ajanted un daolenn evit se, hag implijet an daolenn evit sevel ar rest anezhi. E pre-alfa serret emañ, da lavaret eo e vez mat, dre vras, evit ur bochad mignoned. Pajenn priz ebet, lizher-keleier ebet, plan kresk ebet. M'hoc'h eus c'hoant, gallout a rit goulenn e amprouiñ p'en em zigoro un tammig muioc'h."]},{"n":144,"texts":["AI-gile zo un daolenn kanban evit un den ha kalz ajanted AI. Red a ra war hoc'h urzhiater deoc'h-c'hwi ha digoust eo penn-da-benn. Ouzhpennañ a rit raktresoù, ha pep raktres a zeu gant ur penn-skipailh hag ur skipailh bihan. Flapañ a rit gant ar penn-skipailh, un tammig evel war Discord, ha deskrivañ ur mennozh; ar penn-skipailh a laka anezhañ da gartennoù ha da blan, goude-se e c'hortoz ma wasit war Go. Ar skipailh a labour ar c'hartennoù hervez o raktres, dre un urzhiad-linenn simpl graet evit modeloù yezh. Kent ma teuio tra ebet en-dro deoc'h, un amprouer AI a heul ar pazennoù en un eilad eus an arload hag a stag ur skeudenn skramm. Al labour echu a zeu en ho pern gant ar restroù cheñchet hag an diforc'h. Asantiñ a rit, pe skrivit un evezhiadenn hag ar skipailh a zihun hag a glask en-dro. Hepken c'hwi a c'hall dilec'hiañ ur gartenn da Graet. Kont ebet, heulier ebet, koukiz ebet, ha pep tra a chom war hoc'h urzhiater.","Un devezh gant AI-gile, tro-dro. Da noz e lezit un nebeut evezhiadennoù: ar bouton-mañ zo e plas fall, ar roll-se a rankfe bezañ rummet, ha ne vefe ket un doare teñval. Mont a rit da gousket. An ajanted a lenn an evezhiadennoù, a ra ar cheñchamantoù, a amprouf anezho hag a gas en-dro deoc'h. Ma teu Da ober da vezañ goullo, ar gward-noz a leun anezhañ diwar ar backlog gant kartennoù na c'houlennont ket respont diganeoc'h. Da vintin ur bern berr zo: un nebeut goulennoù hag un nebeut traoù da amprouiñ, pep hini gant pazennoù a c'hall heuliañ un den kousket-koazh ha gant ur skeudenn skramm eus an dra o labourat. Klikañ a rit dre-hont, asantiñ ar re vat ha kas en-dro ar re all. Ur jedour tokenoù a ziskouez ar pezh en deus implijet an holl, ha No Token Mode zo evit ar sizhunioù treut. Goude-se e tebrit ho pred-vintin, ha n'hall ket an ajanted sikour ac'hanoc'h c'hoazh.","Da gentañ, petra n'eo ket AI-gile. N'eo ket ur startup, n'eo ket da werzhañ, ha den ne zastum ho roadennoù. Un daolenn digoust eo a red war hoc'h urzhiater, hep kont, hep heulier ha hep koukiz. Ar pezh eo: ur plas kempenn m'hallit gwelet holl raktresoù kodiñ AI war un dro, gant ur skipailh ajanted a ra ar c'hartennoù ha c'hwi a ra an divizoù. Kenstrollañ a ra ar c'hartennoù kar, reizhañ a ra an titloù mesk, ha selaou a ra penaos e chom skañv ar c'hod. Komz a ra tro-dro 120 yezh, eus an nederlandeg hag ar flamanteg betek ar pirat hag ar c'hlingon. Ar mignoned a c'hall skrivañ an eil d'egile, e prevez ha sifret. Savet eo bet gant Rich hag un niver bras a ajanted a-bouez, dre implijout e-unan peurliesañ. E pre-alfa serret emañ, setu garv eo a-wechoù. M'hoc'h eus c'hoant, goulennit gant jentilezh ha marteze e vo digor deoc'h abred."]}],"quips":{"1":"Ur ger. Dispont. Re zispont marteze.","3":"Tri ger. Muioc'h onest dija eget an darn vrasañ eus ar pajennoù produioù.","8":"Eizh ger. Berroc'h c'hoazh eget ur stand-up.","21":"Ar hirderioù zo story points, dre-vras. Evel just e int.","55":"Pemp ha hanter-kant ger. Div gartenn zo bet echu e-keit ha ma lennit.","144":"Honnezh eo an hini hir. 233 ebet. An ajanted zo aet da gousket."}},"timeline":{"first-idea.name":"Ar c'hentañ mennozh","first-idea.line":"Ar c'hentañ kaozeadenn a-bezh, a-raok ma vije kod ebet.","first-board.name":"Ar c'hentañ taolenn","first-board.line":"Un daolenn a heul he c'hrouidigezh: kartennoù, bannoù, riklañ-ha-lezel, raktresoù.","team-roles.name":"Skipailh ha rolloù","team-roles.line":"Profiloù ajanted, patromoù skipailh, plasoù ha piv a ra petra.","install.name":"Staliañ ha stummoù","install.line":"Ur zip a c'hall ur mignon staliañ, hizivadur emgefreek, kanolioù ha distro d'ar penn-kentañ.","usage-saver.name":"Espern implij","usage-saver.line":"Muzuliañ ar pezh a gousto ar redadennoù, mirout ar c'hod skañv, espern ho harzh.","friends.name":"Mignoned ha rannañ","friends.line":"Kemennadennoù prevez, un adlavar sifret, pedadennoù, rolloù ha raktresoù rannet.","languages.name":"Yezhoù","languages.line":"Pep skrid skramm en ur restr yezh, an nederlandeg hag ar flamanteg da gentañ.","ai-tester.name":"Amprouer AI","ai-tester.line":"Un amprouer a wiriekaat pep treuzkas da gentañ hag a ziskouez ar pezh en deus gwelet.","website.name":"al lec'hienn","website.line":"aigile.lol, ar rakskeudenn hag an amzeriadur-mañ.","streaming.name":"Flap ha streamiñ","streaming.line":"Discord, Twitch, OBS, mod streamer, GIFoù hag emojioù.","no-ai.name":"Stumm hep AI","no-ai.line":"Un daolenn evit tud a god hep AI, ha taolennoù foran.","night-watch.name":"Gward-noz","night-watch.line":"Ur gward ha Scrum Master a vir ar skipailhoù war al labour p'emaoc'h o kousket.","p-more.name":"Kement tra all","p-more.line":"Mennozhioù bihanoc'h a c'hortoz c'hoazh o zro.","p-android.name":"Pellgomzer ha Android","p-android.line":"Tizhout ho taolenn diwar ur pellgomzer, goude-se un arload Android a-orin.","p-release.name":"Alfa ha pelloc'h","p-release.line":"Alfa serret, al lec'hienn vev, goude-se beta.","p-languages.name":"Muioc'h a yezhoù","p-languages.line":"130 yezh, hag ur mod beuzidigezh evit an deskarded.","p-engines.name":"Muioc'h a vekanikoù AI","p-engines.line":"Dibabit Claude, Codex, Gemini, Copilot pe Cursor evit pep ajant.","p-pro.name":"Boaz a vicherour","p-pro.line":"Skritelloù riskl, dorioù kenaozañ, kartennoù darvoud ha bannoù-diwall.","p-self.name":"Kempenn ac'hanoc'h","p-self.line":"Mod skuizh, kemennoù evit ober war-dro ac'hanoc'h ha 4:20.","p-servers.name":"Servijerioù ha brasaat","p-servers.line":"Arventennoù servijer hollek, rolloù ha plan evit kreskiñ.","p-livestream.name":"Ouzhpennoù streamiñ","p-livestream.line":"Flap Twitch, emojioù personel ha gwel foran bev."},"words":{"button":"📖 Gerioù ar vicher","h":"📖 Gerioù displeget","intro":"Ur stummadur digoust e yezh sklaer: an holl c'herioù a gavot adalek an ideenn gentañ betek ur servij a gont an dud warnañ, gant Agile, ar sevel, ar surentez hag al labour gant an AI a-hed an hent.","search":"Klask ur ger…","none":"Ger ebet ne glot.","close":"Serriñ","count":{"one":"{count} ger","other":"{count} ger"},"groups":[{"id":"idea","name":"💡 Ideenn ha dizoloadur"},{"id":"plan","name":"🗺️ Steuñviñ al labour"},{"id":"agile","name":"🔁 Doareoù labourat Agile"},{"id":"build","name":"🛠️ E sevel"},{"id":"test","name":"🧪 Testoù ha perzhded"},{"id":"change","name":"🔀 E cheñch hep risk"},{"id":"run","name":"🛎️ Lakaat ur servij da vont en-dro"},{"id":"sec","name":"🔒 Surentez ha prevezded"},{"id":"ai","name":"🤖 Labourat gant an AI"},{"id":"money","name":"💰 Arc'hant ha lañvazioù"}],"list":[{"id":"discovery","g":"idea","word":"Dizoloadur","text":"Ar prantad kentañ, pa glasker gouzout peseurt kudenn a dalv ar boan bezañ diskoulmet hag evit piv, a-raok sevel tra pe dra.","also":["prantad dizoloiñ","discovery"]},{"id":"problemstmt","g":"idea","word":"Displegadur ar gudenn","text":"Ur frazenn pe ziv o lavarout piv en deus ur gudenn, petra eo ha perak eo pouezus, evit ma pal an holl ar memes tra.","also":["displegadurioù ar gudenn","problem statement"]},{"id":"user","g":"idea","word":"Implijer","text":"Un den a implij ar pezh a sevit. Evit respont d'e ezhommoù e vez graet al labour.","also":["implijerien"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Perzhiad","text":"Kement den a ra van eus disoc'h al labour pe a vez tizhet gantañ, evel ar re a bae evitañ, ar re a implij anezhañ pe ar re a skoazell anezhañ.","also":["perzhidi","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Un den ijinet met gwirheñvel a zo e-lec'h ur seurt implijer, evit ma c'hallfe ar skipailh goulenn: « Ha kavout a rafe Sam se aes? »","also":["personaoù"]},{"id":"userresearch","g":"idea","word":"Enklask implijerien","text":"Komz gant tud wir ha sellet outo evit gouzout petra o deus ezhomm, e-lec'h divinout.","also":["atersadennoù gant implijerien"]},{"id":"journey","g":"idea","word":"Hent an implijer","text":"Ar pazennoù a ra un den evit kas un dra da benn, adalek ar wech kentañ ma klev komz anezhañ betek ar fin, er-maez eus ho produ ivez. O tresañ anezho e weler pelec'h e chomont stag.","also":["hentoù an implijer","hent ar c'hliant"]},{"id":"painpoint","g":"idea","word":"Poent poanius","text":"Un dra a heskin an dud pe a zale anezho hiziv. Ar produioù mat a lam kuit ar poentoù poanius.","also":["poentoù poanius","pain point"]},{"id":"assumption","g":"idea","word":"Rakkredenn","text":"Un dra a gredit met n'hoc'h eus ket gwiriet c'hoazh. Skrivañ ar rakkredennoù a ziskouez petra da amprouiñ da gentañ.","also":["rakkredennoù","assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Kendezenn","text":"Un divinadenn ar gwellañ a fell deoc'h gwiriañ, gant ar pezh a c'hortozit, evel « an dud en em enskrivo ma vez digoust ar miz kentañ ».","also":["kendezennoù","hipotezenn","hypothesis"]},{"id":"experiment","g":"idea","word":"Arnodenn","text":"Un arnodenn vihan, prientet mat, evit gouzout hag-eñ ez a un ideenn en-dro, a-raok riskañ kalz warni.","also":["arnodennoù","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Un esae buan ha diwar-vras evit gwelet ha gallout a ra un ideenn mont en-dro tamm ebet. Peurliesañ e vez taolet kuit pa vez kavet ar respont.","also":["PoC","proof of concept","prouenn a soñj"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Ur skouer gentañ eus ar produ, skeudennoù a c'haller klikañ warno alies, evit esaeañ an ideenn gant tud a-raok e sevel evel ma zere.","also":["prototipoù"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Un tres simpl eus ur skramm o tiskouez pelec'h e vo lakaet an traoù, hep livioù nag endalc'had gwir.","also":["wireframes","tres skramm"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Ur skeudenn resis eus neuz ur skramm, gant livioù ha testennoù gwir, met n'eus netra o vont en-dro c'hoazh.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Abegadur ar raktres","text":"An abegoù evit kas ur raktres: pegement e koust, petra a zegas pe a espern, hag ar riskloù.","also":["business case","business cases"]},{"id":"feasibility","g":"idea","word":"Gallusted","text":"Ha gallout a reer da vat sevel un dra ha derc'hel anezhañ gant an amzer, an arc'hant hag ar barregezhioù hoc'h eus.","also":["gallus"]},{"id":"outcome","g":"idea","word":"Disoc'h","text":"Ar c'hemm a fell deoc'h evit an dud, evel nebeutoc'h a emgavioù c'hwitet. Pouezusoc'h eo eget ar c'hementad a sevit.","also":["disoc'hioù"],"noTip":1},{"id":"output","g":"idea","word":"Produ-labour","text":"Un dra a ra ar skipailh, evel ur skramm nevez pe un danevell. N'eo ket dre ma'z eo bet graet e sikour unan bennak.","also":["produoù-labour"],"noTip":1},{"id":"successmetric","g":"idea","word":"Muzul berzh","text":"Un niver a lavar deoc'h ha graet en deus al labour ar pezh a oa gortozet digantañ, evel muioc'h a dud oc'h echuiñ o urzhiadenn.","also":["muzulioù berzh","success metric"]},{"id":"kpi","g":"idea","word":"Meneger pennañ (KPI)","text":"Un niver pouezus a evezhiit evit gouzout hag-eñ ez a mat an traoù, evel an niver a enskrivadurioù bep sizhun.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Palioù ha disoc'hioù pennañ (OKR)","text":"Un doare da lakaat palioù: ar pal a lavar petra a fell deoc'h, hag un nebeud disoc'hioù pennañ eo an niverennoù a ziskouez ez oc'h erruet.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produ","text":"An dra a vez savet ha kempennet evit e implijerien, evel un arload, ul lec'hienn pe un ostilh.","also":["produoù"],"noTip":1},{"id":"vision","g":"plan","word":"Gweledigezh ar produ","text":"Ur frazenn verr a lavar piv a vez skoazellet gant ar produ ha war-zu pelec'h ez a war hir dermen.","also":["vision statement","gweledigezh"]},{"id":"po","g":"plan","word":"Perc'henn ar produ (PO)","text":"An den a ziviz petra a vez savet ha dre beseurt urzh, evit ma labourfe ar skipailh atav war ar pezh a bouez ar muiañ. E AI-gile, c'hwi eo.","also":["PO","product owner"]},{"id":"pm","g":"plan","word":"Merour produ (PM)","text":"An den a ra war-dro roud ur produ: peseurt kudennoù a ziskoulm, evit piv ha perak. PM a c'hall talvezout « project manager » ivez, gwiriit petra eo.","also":["product manager","merourien produ"]},{"id":"projmgr","g":"plan","word":"Merour raktres","text":"An den a ziwall ma chomo ur raktres en e amzer hag en e vudjed, oc'h heuliañ piv a ra petra ha betek pegoulz.","also":["project manager","merourien raktres"]},{"id":"roadmap","g":"plan","word":"Roadmap (treuzfollenn)","text":"Ur steuñv diwar-vras eus ar pezh a zeuio er mizioù a zeu, en urzh. Diskouez a ra an tu, ket deiziadoù resis, ha cheñch a ra a-feur ma teskit.","also":["roadmaps","treuzfollenn"]},{"id":"milestone","g":"plan","word":"Maen-bonn","text":"Ur poent er raktres a dalv ar boan bezañ merket, evel « kentañ stumm enlinenn » pe « 100 implijer ».","also":["mein-bonn","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Produ bihanañ talvoudus (MVP)","text":"Ar stumm bihanañ eus ur produ a zo talvoudus c'hoazh evit tud wir, evit gallout deskiñ diganto abred.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Ezhomm","text":"Un dra a rank ar produ echu ober pe bezañ.","also":["ezhommoù"],"noTip":1},{"id":"scope","g":"plan","word":"Scope (ledander)","text":"Ar pezh a zo e-barzh al labour ha, ken pouezus all, ar pezh n'eo ket.","also":["scope","ledander al labour","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep (ledander o kreskiñ)","text":"Pa vez ouzhpennet muioc'h-mui a draoù d'al labour tamm-ha-tamm, hep emglev diwar-benn an amzer pe ar c'houst ouzhpenn, ha ne vez echu biken da vat.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Arc'hwel","text":"Un dra a c'hell ar produ ober evit an dud, evel « adderaouekaat ho ker-tremen ».","also":["arc'hwelioù","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Ur bern labour, re vras evit bezañ graet en un taol, setu e vez troc'het e kartennoù bihanoc'h.","also":["epics"]},{"id":"story","g":"plan","word":"Istor implijer","text":"Un tamm labour bihan skrivet diouzh tu an implijer: « Evel prener e fell din enrollañ ma faner, evit echuiñ diwezhatoc'h. » Digeriñ a ra ar gaoz diwar-benn ar pezh da sevel.","also":["user stories","istorioù implijer"]},{"id":"ac","g":"plan","word":"Dezverkoù degemer (AC)","text":"Ar gwiriadennoù a rank ur gartenn tremen evit bezañ sellet evel echu, emglevet a-raok kregiñ, evel « emañ ar paner c'hoazh goude bezañ digevreet hag adkevreet ».","also":["acceptance criteria","dezverkoù degemer"]},{"id":"task","g":"plan","word":"Kefridi","text":"Ul labour hepken da ober, alies ur bazenn vihan eus un istor brasoc'h.","also":["kefridioù","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiked (ticket)","text":"Un anv all evit ur gartenn: un tamm labour pe ur goulenn, heuliet adalek ar penn-kentañ betek ar fin.","also":["ticket","tickets","tikedoù"]},{"id":"priority","g":"plan","word":"Kentelezh","text":"Pegen pouezus pe mallus eo un dra e-keñver an holl draoù all, evit ma vo graet al labour pouezusañ da gentañ.","also":["kentelezhioù","priority"],"noTip":1},{"id":"prioritise","g":"plan","word":"Renkañ dre gentelezh","text":"Lakaat al labour en urzh hervez e bouez. Un doare boutin eo MoSCoW: Ret (Must), Dleet (Should), Gallus (Could), Ket ar wech-mañ (Won't).","also":["kentelezhiañ","MoSCoW"]},{"id":"estimate","g":"plan","word":"Priziadenn","text":"Un divinadenn ar gwellañ eus ment pe padelezh un tamm labour. Un divinadenn eo, ket ur bromesa.","also":["priziadennoù","priziañ","estimate"],"noTip":1},{"id":"storypoints","g":"plan","word":"Poentoù istor","text":"Un doare da vrasjediñ ment al labour en ur geñveriañ ar c'hartennoù an eil ouzh eben (« war-dro div wech brasoc'h eget houmañ ») kentoc'h eget e eurioù. N'int ket evit keñveriañ ar skipailhoù.","also":["story points","poent istor"]},{"id":"tshirt","g":"plan","word":"Mentoù T-shirt","text":"Brasjediñ ment al labour gant S, M, L pe XL. Buan ha mat a-walc'h evit ar steuñviñ kentañ.","also":["t-shirt sizes","S M L XL"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Ur c'hoari evit priziañ: an holl a ziskouez ur gartenn vent war un dro, ha goude e tispleg an hini uhelañ hag an hini izelañ perak.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dalc'hiadur","text":"Pa ne c'haller ket kregiñ pe echuiñ un tamm labour ken na vo graet unan all.","also":["dalc'hiadurioù","dependency"]},{"id":"blocker","g":"plan","word":"Sac'h","text":"Kement tra a vir ouzh al labour da vont war-raok bremañ, evel ur respont a vank pe un ostilh torret.","also":["sac'hioù","stanker","blocker"]},{"id":"deadline","g":"plan","word":"Termen","text":"An deiziad ma rank bezañ echu un dra.","also":["termenoù","deiziad termen","deadline"],"noTip":1},{"id":"deliverable","g":"plan","word":"Disoc'h da reiñ","text":"Un dra fetis a vez produet gant al labour ha roet, evel ur bajenn a ya en-dro pe un danevell.","also":["disoc'hoù da reiñ","deliverable"]},{"id":"forecast","g":"plan","word":"Rakwel","text":"Un diougan eus ar pezh a c'hoarvezo moarvat, evel pegoulz e vo echu al labour, diouzh ar pezh a ouzer betek-henn.","also":["rakwelioù","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Muzul","text":"Kement tra a vuzuliit hag a heuliit a-hed an amzer, evel gweladennoù ur bajenn pe an amzer a bad ur reizhadenn.","also":["muzulioù","metric"]},{"id":"feedback","g":"plan","word":"Distro","text":"Ar pezh a lavar an dud deoc'h diwar-benn ho labour, mat pe fall. E gaout abred hag alies eo kalon Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Roll gortoz an ideennoù hag al labour n'int ket bet steuñvet c'hoazh, ar re bouezusañ e penn uhelañ. Ne vez labouret war netra eno ken na vez kaset da Da ober."},{"id":"sprint","g":"agile","word":"Sprint","text":"Ur prantad labour berr ha divoug (ur sizhun pe ziv alies, biken muioc'h eget ur miz) gant ur pal hag ur strollad kartennoù emglevet da echuiñ.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un emvod berr bemdez: petra en deus graet pep ezel eus ar skipailh, petra a raio war-lerc'h, ha petra a vir outañ da vont war-raok. E Scrum e vez anvet « daily scrum ».","also":["standup","stand-ups","daily scrum","daily stand-up","emvod pemdeziek"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Un doare labourat ma tremen ar c'hartennoù dre vannadoù ur bord (evel Da ober, O vont war-raok, Graet) ha ma vevenn ar skipailh pegement a labour a vez war ar stern war un dro, evit ma kendalc'hfe al labour da redek."},{"id":"wip","g":"agile","word":"Bevenn WIP","text":"WIP eo berradur « work in progress » (labour war ar stern). Ur vevenn WIP eo an niver brasañ a gartennoù a dlefe bezañ en ur bannad war un dro, evit ma echufe ar skipailh an traoù a-raok kregiñ gant re all.","also":["WIP"]},{"id":"dod","g":"agile","word":"Despizadur Echu","text":"Roll-gwiriañ berr ar skipailh war ar pezh a dalvez “echu”, evel amprouet ha displeget, a-raok ma vo roet ur gartenn deoc'h. E c'hevell, an Despizadur Prest, a lavar pegoulz eo sklaer a-walc'h ur gartenn evit kregiñ.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Sell war-geñver","text":"Ur sell war-gil reoliek ouzh an doare ma labour ar skipailh, evit en em glevout war un dra pe ziv da ober gwelloc'h ar wech a zeu. Berradur « retrospective ». En AI-gile e kinnig ur retro ur c'hemm en doareoù labourat ar skipailh, ha c'hwi a lavar Go pe Ket c'hoazh.","also":["retro","retrospective"]},{"id":"swarm","g":"agile","word":"Strollad","text":"An holl d'ar stern: kalz tud a laosk o labour all evit reizhañ asambles un dra mallus betek ma vo diskoulmet. En AI-gile e sikour an holl skipailhoù war ur raktres, ha gortoz a ra ar raktresoù all e-keit-se.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"E Scrum, an den a sikour ar skipailh da labourat mat: lemel a ra ar pezh a vir outañ da vont war-raok, ober a ra ma chomo an emvodoù war an hent mat ha kelenn a ra boazioù mat, hep bezañ mestr da zen. En AI-gile e kav al Lead Scrum Master ar c'hartennoù stag, broudañ a ra ar skipailhoù hag e tegas da soñj deoc'h eus ar pezh a c'hortoz, en holl raktresoù.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Un doare da labourat a bazennoù bihan: sevel un tammig, diskouez disoc'hoù gwir alies, deskiñ diouzh ar pezh a lavar an dud ha cheñch ar steuñv a-hed an hent, e-lec'h steuñviñ pep tra en a-raok.","also":["Agile development","doareoù labourat agile"]},{"id":"manifesto","g":"agile","word":"Manifesto Agile","text":"Un disklêriadur berr skrivet e 2001 gant krouerien meziantoù. Lakaat a ra an dud, an disoc'hoù a ya en-dro, al labour tost gant ar c'hliant hag ar respont d'ar c'hemmoù a-raok ar steuñvioù pounner hag ar paperachoù.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall (doare dourlamm)","text":"An doare labourat kozh: steuñviñ pep tra, goude sevel pep tra, goude testiñ pep tra, ur bazenn war-lerc'h eben. Diaes ha ker eo cheñch traoù diwezhat.","also":["waterfall model","dourlamm"]},{"id":"iteration","g":"agile","word":"Iteradenn","text":"Un tro evit sevel un dra, e wiriañ hag e wellaat. Ur chadenn anezho eo al labour Agile, hag ur sprint a zo ur seurt anezho.","also":["iteradennoù","iteration"]},{"id":"increment","g":"agile","word":"Kresk","text":"Ur pezh nevez a ya en-dro, ouzhpennet d'ar produ e-pad ur sprint pe un tro labour, hag a glot gant ar pezh a oa endeo.","also":["kreskoù","increment"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Un doare labourat Agile brudet: ur skipailh bihan a labour e sprintoù berr war-zu ur pal, gant rolloù termenet hag un nebeud emvodoù reoliek evit steuñviñ, gwiriañ ha gwellaat."},{"id":"scrumteam","g":"agile","word":"Skipailh Scrum","text":"Ar strollad bihan a ra al labour e Scrum: ur perc'henn produ, ur Scrum Master hag an diorroerien.","also":["skipailhoù Scrum"]},{"id":"ceremonies","g":"agile","word":"Emvodoù Scrum","text":"An emvodoù reoliek e Scrum: steuñviñ ar sprint, ar scrum pemdeziek, adwel ar sprint hag ar retro. Kalz a dud a ra « ceremonies » anezho.","also":["Scrum events","ceremonies","Scrum ceremonies","lidoù Scrum"]},{"id":"sprintplan","g":"agile","word":"Steuñviñ ar sprint","text":"An emvod e penn kentañ ur sprint ma kav ar skipailh un emglev diwar-benn perak eo pouezus ar sprint, peseurt kartennoù da gemer ha penaos kregiñ.","also":["planning meeting","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Pal ar sprint","text":"Ur frazenn a lavar da betra e servij ur sprint. Ar c'hefridioù bihan a c'hall cheñch a-hed an hent, gant ma vo tizhet ar pal.","also":["sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog ar sprint","text":"Ar c'hartennoù dibabet evit ar sprint a-vremañ, gant steuñv ar skipailh evit o ober.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog ar produ","text":"Ar roll klok, renket, eus kement tra a c'hallfe bezañ savet evit ar produ, ar re bouezusañ e penn uhelañ. Cheñch a ra bepred a-feur ma teskit.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Pal ar produ","text":"An disoc'h brasoc'h a glask ar produ tizhout, hag a sikour ar skipailh da zibab petra ober war-lerc'h.","also":["product goal","product goals"]},{"id":"refinement","g":"agile","word":"Kempenn ar backlog","text":"Mont dre ar backlog ingal evit kempenn, rannañ, renkañ ha resisaat ar c'hartennoù, evit ma vint prest da vezañ kemeret. Lavaret e vez ivez « backlog grooming ».","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Adwel ar sprint","text":"Un emvod e dibenn ur sprint ma tiskouez ar skipailh ar pezh en deus echuet ha ma klev petra a soñj an dud, evit divizout petra a zeuio war-lerc'h.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Diskouez al labour echu o vont en-dro, war-eeun, d'ar re o doa goulennet anezhañ.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox (amzer bevennet)","text":"Ur c'hementad amzer divoug evit un dra. Pa vez tremenet, e paouezit, ha pa ne vefe ket graet pep tra.","also":["timeboxed","timeboxes","amzer bevennet"]},{"id":"velocity","g":"agile","word":"Tizh (velocity)","text":"Pegement a labour a echu ur skipailh peurvuiañ en ur sprint, implijet evit steuñviñ pegement kemer ar wech all. N'eo ket un notenn evit muzuliañ pegen start e labour an dud.","also":["team velocity","tizh ar skipailh"]},{"id":"capacity","g":"agile","word":"Barregezh labour","text":"Pegement a labour a c'hall ar skipailh kemer war e gein e-pad ur prantad, goude bezañ lamet ar vakañsoù hag al labourioù all.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart (grafik al labour a chom)","text":"Ur grafik eus al labour a chom en ur sprint, o tiskenn deiz goude deiz. Ma chom al linenn plaen, ez eus un dra stag.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart (grafik al labour graet)","text":"Ur grafik eus al labour echu o pignat gant an amzer, e-kichen ar sammad steuñvet, evit gwelet pegoulz e vo tizhet.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Bord Kanban","text":"Ar bord e-unan: ur bannad evit pep pazenn eus al labour, ha kartennoù o vont eus an eil d'egile.","also":["Kanban boards","bordoù Kanban"]},{"id":"pullsys","g":"agile","word":"Reizhiad tennañ (pull)","text":"Un doare labourat ma ne grog ul labour nevez nemet pa'z eus lec'h gant unan bennak evit e gemer, e-lec'h bezañ bountet war ur plad leun dija.","also":["pull-based","pull system"]},{"id":"flow","g":"agile","word":"Lanv (flow)","text":"Pegen dic'hlaou ez a al labour a-dreuz ar bord. Ul lanv mat a dalvez e kendalc'h ar c'hartennoù da vont war-raok kentoc'h eget en em bilat.","also":["flow","flow of work","lanv al labour"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (amzer evit ober)","text":"Pegeit e pad adalek ma c'houlenn unan bennak un dra betek ma vez echu.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time (amzer labour)","text":"Pegeit e pad ur gartenn adalek ma krog al labour warni da vat betek ma vez echu.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput (feur echuiñ)","text":"Pet kartenn a vez echuet en ur sizhun, pe e-pad ur prantad all bennak.","also":["throughput rate","feur echuiñ"]},{"id":"bottleneck","g":"agile","word":"Strizhenn","text":"Ar bazenn ma en em bil al labour hag a ziboell kement tra a zo war he lerc'h, evel gouzoug strizh ur voutailh.","also":["strizhennoù","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Renk (swimlane)","text":"Ur renk a-dreuz ar bord a strollad kartennoù eus ar memes seurt, evel al labour mallus pe kartennoù ur skipailh.","also":["swimlanes","swim lane","renkoù"]},{"id":"lean","g":"agile","word":"Lean","text":"Un doare labourat a lam ar foranoù (kement tra na sikour ket ar c'hliant) hag a laka al labour da redek dic'hlaou."},{"id":"waste","g":"agile","word":"Foran","text":"E Lean, kement tra a goust strivoù hep sikour ar c'hliant, evel gortoz, adober pe sevel traoù na vez implijet gant den.","noTip":1},{"id":"kaizen","g":"agile","word":"Gwellaat dalc'hmat","text":"Gwellaat un tammig bepred dre gemmoù bihan ha reoliek, ha gwiriañ goude o deus sikouret. Ar retroioù a zo un doare d'en ober. Lavaret e vez ivez kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Skipailh emaozet","text":"Ur skipailh a ziviz e-unan penaos ober al labour, kentoc'h eget bezañ lavaret dezhañ pazenn ha pazenn.","also":["self-organising","self-managing team","emaozañ"]},{"id":"crossfunc","g":"agile","word":"Skipailh lieskefridi","text":"Ur skipailh en deus an holl varregezhioù ret evit echuiñ al labour e-unan, evel an dezverkañ, ar sevel hag an testiñ.","also":["cross-functional","lieskefridi"]},{"id":"spike","g":"agile","word":"Spike","text":"Un enklask berr ha bevennet en amzer evit respont d'ur goulenn a-raok en em ouestlañ d'al labour gwir.","also":["spikes"]},{"id":"rework","g":"agile","word":"Adober","text":"Ober al labour en-dro peogwir ne oa ket reizh ar wech kentañ.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agile war skeul vras (SAFe)","text":"Doareoù da implijout Agile gant kalz skipailhoù en un aozadur bras. SAFe (Scaled Agile Framework) a zo ur skouer brudet.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Teuliad kod ar raktres gant istor klok e gommitoù. Gallout a ra bezañ war hoc'h urzhiataer, war GitHub, pe en daou lec'h.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Ul linenn labour distag er c'hod, evit ober kemmoù hep stokañ ouzh ar stumm pennañ.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Ur skeudenn enrollet eus ar c'hod, gant ur notenn verr diwar-benn ar pezh a zo cheñchet. Gallout a rit mont en-dro da unan bepred.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Kas ho skeudennoù enrollet (commitoù) eus an urzhiataer-mañ d'an eilskrid boutin enlinenn, evel GitHub, evit ma vefent gwarezet ha ma c'hallfe ar re all o c'haout."},{"id":"merge","g":"build","word":"Merge","text":"Unaniñ kemmoù ur branch en unan all, peurliesañ en-dro er stumm pennañ."},{"id":"pr","g":"build","word":"Pull request","text":"Goulenn ma vo gwiriet kemmoù ur branch ha unanet er stumm pennañ. Lec'hiennoù zo a lavar « merge request ».","also":["PR","PRs","merge request","pull request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kempenn ar c'hod hep cheñch ar pezh a ra: restroù bihanoc'h, anvioù sklaeroc'h, nebeutoc'h a adlavar."},{"id":"bug","g":"build","word":"Bug","text":"Un dra ne labour ket evel ma tle.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Adwelet kenstrollet","text":"Un eil daoulagad: unan all estreget an aozer a wir al labour a-raok ma teu betek ennoc'h, evit ma tremenfe nebeutoc'h a fazioù. En AI-gile e vez gwiriet pep kartenn gant un AI all.","also":["adwelet ar c'hod","peer review","code review"]},{"id":"code","g":"build","word":"Kod","text":"An urzhioù skrivet a lavar d'un urzhiataer petra ober. Lavaret e vez ivez « kod tarzh » (source code).","also":["source code","kod tarzh"],"noTip":1},{"id":"proglang","g":"build","word":"Yezh programmiñ","text":"Ur yezh evit skrivañ kod, evel JavaScript, Python pe Java. Mat eo pep hini evit labourioù disheñvel.","also":["programming languages","yezhoù programmiñ"]},{"id":"developer","g":"build","word":"Diorroer (dev)","text":"Unan a skriv hag a gemm kod. Lavaret e vez ivez programmer pe software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Meziant","text":"Ar programmoù a ya en-dro war an urzhiataerioù hag ar pellgomzerioù, d'ober an diforc'h gant ar mekanikoù o-unan (ar periant, hardware).","noTip":1},{"id":"app","g":"build","word":"Arload","text":"Ar ger berr evit « application » e saozneg: ur programm a implij an dud evit kas un dra da benn, war ur pellgomzer, un urzhiataer pe en ur merdeer web.","also":["apps","app","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Arload web","text":"Un arload a ya en-dro en ur merdeer web, ma n'eus netra da staliañ.","also":["web apps","web application","arloadoù web"]},{"id":"frontend","g":"build","word":"Front end","text":"Al lodenn eus un arload a welit hag a glikit warni: ar skrammoù, ar boutonoù hag ar gerioù, en ho merdeer alies.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Al lodenn kuzh eus un arload a vir ar roadennoù hag a ra al labour pa glikit war un dra bennak, evel gwiriañ ho ker-tremen.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Labourat war ar front end hag ar back end war un dro.","also":["full-stack"]},{"id":"ui","g":"build","word":"Etrefas implijer (UI)","text":"Ar pezh a wel hag a implij un den war ar skramm: an aozadur, ar boutonoù, al lañserioù hag an testenn.","also":["UI","user interface","etrefas"]},{"id":"ux","g":"build","word":"Skiant-prenet an implijer (UX)","text":"An doare ma kaver implijout un dra: aes, sklaer ha plijus, pe luziet ha gorrek.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Haezadusted (a11y)","text":"Ober traoù a c'hall an holl implijout, en o zouez an dud na welont ket mat, na c'hallont ket implijout ul logodenn pe a implij ul lenner skramm.","also":["a11y","accessibility","haezadus"]},{"id":"responsive","g":"build","word":"Design azasaus (responsive)","text":"Ober ma'z a ar pajennoù d'ar vent hag ez eont mat en-dro war pep ment skramm, eus ur pellgomzer betek ur skramm bras.","also":["responsive design","azasaus"]},{"id":"designsys","g":"build","word":"Reizhiad design (design system)","text":"Ur pakad boutin a livioù, a fontoù, a boutonoù hag a reolennoù, evit ma vo heñvel neuz ha doare pep skramm.","also":["design system","design systems"]},{"id":"architecture","g":"build","word":"Tisavouriezh (architecture)","text":"Stumm hollek ur reizhiad: peseurt lodennoù pennañ a zo ennañ ha penaos e komzont an eil gant egile."},{"id":"database","g":"build","word":"Stlennvon (DB)","text":"Ur stal titouroù urzhiet mat, evel ul liammenn jediñ galloudus-tre a c'hall an arload lenn ha kemmañ.","also":["database","databases","DB","stlennvonioù","diaz roadennoù"]},{"id":"schema","g":"build","word":"Brastres ar stlennvon (schema)","text":"Aozadur ur stlennvon: peseurt taolennoù titouroù a zo ennañ ha petra a ya e pep hini.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Berradur « structured query language »: ar yezh implijet evit goulenn titouroù digant kalz stlennvonioù pe evit o c'hemmañ.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Roadennoù","text":"Titouroù miret gant un urzhiataer, evel anvioù, urzhiadennoù pe arventennoù.","also":["data","dataset","datasets","roadennoù"],"noTip":1},{"id":"server","g":"build","word":"Servijer","text":"Un urzhiataer enaouet bepred a respont da c'houlennoù urzhiataerioù all, evel kas ur bajenn web deoc'h pa weladennit anezhi.","also":["server","servers"]},{"id":"client","g":"build","word":"Kliant","text":"An tu a c'houlenn un dra, peurliesañ ho merdeer pe hoc'h arload, o komz gant ur servijer. E bed ar c'henwerzh e talvez ivez ur c'hliant, ur prener.","also":["client","clients","kliantoù"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Berradur « application programming interface »: ur roll goulennoù termenet a c'hall ur programm ober d'unan all, evel goulenn digant ur servij amzer diougan an amzer evit hiziv.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Un elfenn eus roll goulennoù un API: ur chomlec'h web a c'hall ur programm galv evit kaout pe kas un dra bennak.","also":["endpoints"]},{"id":"integration","g":"build","word":"Enframmadur","text":"Liammañ div reizhiad evit ma labourint asambles, evel ho stal o kas an urzhiadennoù d'ho meziant kontouriezh.","also":["integration","integrations","enframmadurioù"]},{"id":"webhook","g":"build","word":"Webhook","text":"Ur gemennadenn a gas ur reizhiad d'unan all anezhañ e-unan kerkent ha ma c'hoarvez un dra, evel « paeamant resevet ».","also":["webhooks"]},{"id":"library","g":"build","word":"Levraoueg (library)","text":"Kod prest skrivet gant unan all a c'hallit adimplijout e-lec'h e skrivañ hoc'h-unan.","also":["library","libraries","levraouegoù"],"noTip":1},{"id":"framework","g":"build","word":"Framework (frammaozadur)","text":"Ur framm prest evit sevel un arload, a ziviz kalz eus an doare ma vez aozet ar c'hod, evel framm un ti da leuniañ.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Kit diorren meziantoù (SDK)","text":"Ur voestad ostilhoù, kod ha skouerioù evit sevel meziantoù evit ur savenn pe ur servij resis.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Dalc'hiadur meziant","text":"Ul levraoueg pe un ostilh ma'z eus ezhomm anezhañ evit ma'z afe ho kod en-dro. Pouezus eo o hizivaat evit ar surentez.","also":["software dependency","software dependencies","dependency"]},{"id":"package","g":"build","word":"Pakad","text":"Ur pakad kod prest a c'hallit staliañ hag implijout en ur raktres.","also":["package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Merour pakadoù","text":"Un ostilh a bell hag a hizivaa ar pakadoù a zo ezhomm anezho d'ho kod. npm a zo unan boutin.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"An ostilh implijetañ evit mirout istor ar c'hemmoù er c'hod, e stumm commitoù ha branchoù."},{"id":"github","g":"build","word":"GitHub","text":"Ul lec'hienn a vir ar repoioù Git enlinenn, evit ma c'hallfe ar skipailhoù rannañ kod, adwelet kemmoù ha heuliañ al labour."},{"id":"vcs","g":"build","word":"Merañ ar stummoù","text":"Mirout istor klok pep kemm er restroù, evit gwelet piv en deus kemmet petra ha distreiñ war-gil mar bez ezhomm. Git a ra an dra-se.","also":["version control","source control","version control system","mererezh stummoù"]},{"id":"clone","g":"build","word":"Clone","text":"Ober ho eilskrid klok deoc'h-c'hwi eus ur repo, gant e istor, war hoc'h urzhiataer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Pellgargañ ar commitoù diwezhañ eus an eilskrid boutin (evel GitHub) war hoc'h urzhiataer. Ar c'hontrol eus push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branch pennañ (main)","text":"Stumm ofisiel ar c'hod ma labour an holl diwarnañ, anvet main pe master alies.","also":["main branch","master branch"]},{"id":"conflict","g":"build","word":"Tabut merge (merge conflict)","text":"Pa cheñch daou gemm ar memes linennoù e doareoù disheñvel, ha ne c'hall ket an urzhiataer o unaniñ, ha ret eo d'un den dibab.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Ur gwel a ziskouez resis petra zo bet kemmet etre daou stumm: al linennoù ouzhpennet hag al linennoù lamet.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Hoc'h eilskrid deoc'h-c'hwi eus repo unan all, a c'hallit kemmañ hep stekiñ ouzh e hini.","also":["forks","forked"]},{"id":"script","g":"build","word":"Skript","text":"Ur programm berr a ra ul labour hepken e-unan, evel kempenn restroù pe lañsañ an arload.","also":["script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Treiñ ar c'hod en un dra prest da vezañ lañset, pe an disoc'h prest-se e-unan.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Kempunañ (compile)","text":"Treiñ ar c'hod skrivet gant an dud en ur stumm a c'hall an urzhiataer erounit war-eeun.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"Linenn urzhioù (CLI)","text":"Ur prenestr testenn ma skrivit urzhioù d'an urzhiataer e-lec'h klikañ. Lavaret e vez ivez « terminal ».","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Kefluniadur (config)","text":"An arventennoù a ren doare ar meziant, miret a-part diouzh ar c'hod evit ma vefe aes o c'hemmañ.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Argemmenn endro","text":"Un arventenn roet d'ur programm pa loc'h, implijet alies evit chomlec'hioù pe gerioù-tremen evit na vefent ket skrivet er c'hod.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging (dizreinañ)","text":"Klask perak ne ya ket un dra en-dro, hag e reizhañ.","also":["debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Programmiñ a-zaou","text":"Daou zen (pe un den hag un AI) o labourat asambles war ar memes kod, unan o skrivañ hag egile o wiriañ.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Teuliadur (docs)","text":"Displegadennoù skrivet diwar-benn penaos ez a un dra en-dro pe penaos implijout anezhañ.","also":["documentation","docs","teuliadur"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Ar restr gentañ da lenn en ur repo: petra eo ar raktres ha penaos e lakaat da vont en-dro.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Reizhiad kozh (legacy)","text":"Ur reizhiad kozh implijet c'hoazh ha diaes da gemmañ, alies peogwir n'eus nemet nebeut a dud a gompren anezhañ c'hoazh.","also":["legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Dle teknikel","text":"Berradennoù a espern amzer bremañ met a laka ar c'hemmoù da zont da vezañ gorrekoc'h, evel ur prest a gresk e interest. An adframmañ (refactor) a zistaol anezhañ tamm-ha-tamm.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Ur gwiriadenn ez a un dra en-dro evel ma tle. Testoù zo a vez lañset gant an urzhiataer e-unan bep tro ma cheñch ar c'hod; testoù all eo c'hwi oc'h esaeañ ur gartenn echu a-raok he degemer.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Berradur « quality assurance » (gwarant ar berzhded): kement tra a vez graet evit bezañ sur ez eo reizh al labour a-raok mont enlinenn. En AI-gile e talvez ar gwiriadennoù emgefre: pa vez ruz QA, ez eus un dra o deus c'hwitet, ha ne c'hall ket mont enlinenn ken na vo reizhet.","also":["gwiriadennoù perzhded","quality checks"]},{"id":"testpile","g":"test","word":"Stok amprouennoù","text":"Ar c'hartennoù echu a c'hortoz ma vint amprouet ganeoc'h, an eil goude egile. Asantit unan pe adkasit anezhi gant un notenn, hag an hini war-lerc'h a zeu.","also":["stokoù amprouennoù","test pile"]},{"id":"autotest","g":"test","word":"Test emgefre","text":"Ur gwiriadenn a ra an urzhiataer e-unan bep tro ma cheñch ar c'hod, evit kavout ar fazioù abred.","also":["automated test","automated tests","automatic tests","testoù emgefre"]},{"id":"manualtest","g":"test","word":"Test dre zorn","text":"Un den oc'h esaeañ al labour dre zorn evit gwelet ha mont a ra evel ma tleer.","also":["manual test","manual tests","manual testing","testoù dre zorn"]},{"id":"unittest","g":"test","word":"Test unanenn (unit test)","text":"Ur gwiriadenn emgefre vihan eus un tammig kod a-unan.","also":["unit test","unit tests","testoù unanenn"]},{"id":"integtest","g":"test","word":"Test enframmañ","text":"Ur gwiriadenn ez a meur a lodenn en-dro mat asambles, ha n'eo ket hepken unan hag unan.","also":["integration test","integration tests","testoù enframmañ"]},{"id":"endtoend","g":"test","word":"Test penn-da-benn (E2E)","text":"Un test a ra evel un implijer gwir adalek ar penn-kentañ betek ar fin, evel en em enskrivañ, prenañ ha paeañ.","also":["E2E","end-to-end tests","testoù penn-da-benn"]},{"id":"uat","g":"test","word":"Testoù degemer gant an implijerien (UAT)","text":"Ar re o deus goulennet al labour a esa anezhañ o-unan hag a lavar ha graet e vez ar pezh o deus ezhomm. Bern an testoù en AI-gile eo e stumm deus an dra-se.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Kildaol (regression)","text":"Un dra a yae en-dro a-raok hag a zo torret goude ur c'hemm. An testoù kildaol a wiri ez a an traoù kozh en-dro c'hoazh.","also":["regression","regressions","regression test","regression tests","regression testing","kildaol"]},{"id":"smoke","g":"test","word":"Smoke test (test moged)","text":"Ur gwiriadenn vuan-tre evit gouzout hag an traoù pennañ a ya en-dro tamm ebet, da skouer kerkent ha ma'z eo bet lakaet ur c'hemm enlinenn. Ma c'hwit, paouezit ha sellit.","also":["smoke test","smoke tests","test moged"]},{"id":"exploratory","g":"test","word":"Test ergerzhet","text":"Esaeañ ar produ en un doare dieub ha broudañ anezhañ e doareoù disheñvel, evit kavout kudennoù na vefent ket kavet gant ar gwiriadennoù steuñvet.","also":["exploratory test","exploratory tests","exploratory testing","testoù ergerzhet"]},{"id":"testcase","g":"test","word":"Degouezh test (test case)","text":"Ur senario skrivet da esaeañ: ar pazennoù, ha petra a zlefe c'hoarvezout.","also":["test case","test cases","degouezhioù test"]},{"id":"coverage","g":"test","word":"Goloadur an testoù","text":"Pegement eus ar c'hod a vez gwiriet gant testoù emgefre. Muioc'h a zo suroc'h peurliesañ, met ur goloadur uhel e-unan ne brouv ket ez a pep tra mat en-dro.","also":["code coverage","test coverage"]},{"id":"testdata","g":"test","word":"Stlennoù test","text":"Titouroù skouer ijinet, implijet e-pad an testoù, evit na vefe diskuliet titouroù prevez den gwir ebet.","also":["test data","test fixtures","roadennoù test"]},{"id":"edgecase","g":"test","word":"Degouezh bevenn (edge case)","text":"Un degouezh dibar e bevennoù an traoù, evel ur furmskrid goullo pe un anv gant un apostrofenn, ma torr an traoù alies.","also":["edge case","edge cases","degouezhioù bevenn"]},{"id":"happypath","g":"test","word":"Hent eeun (happy path)","text":"An hent boaz ma'z a pep tra mat. Un testiñ mat a esa ivez an hentoù ma'z a an traoù a-dreuz."},{"id":"perftest","g":"test","word":"Testoù digonusted","text":"Gwiriañ pegen buan eo un dra ha penaos e talc'h pa vez gwasket warnañ.","also":["performance testing","performance test","performance tests","digonusted"]},{"id":"loadtest","g":"test","word":"Testoù karg","text":"Gwiriañ penaos e talc'h ur reizhiad pa vez implijet gant kalz a dud war un dro.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Testoù surentez","text":"Klask ar gwanderioù a c'hallfe lezel unan bennak da gamimplij ur reizhiad pe da welet ar pezh na zlefe ket.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Testoù haezadusted","text":"Gwiriañ e c'hall tud gant barregezhioù disheñvel implijout ar produ, gant ul lenner skramm pe gant ur c'hlavier hepken da skouer.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Ur gwiriadenn emgefre a gav ar fazioù tost sur hag ar stil dibourc'h er c'hod, evel ur reizher reizhskrivadur evit ar programmoù.","also":["linter","lint"]},{"id":"static","g":"test","word":"Dielfennañ statek","text":"Gwiriañ ha kudennoù a zo er c'hod en ur lenn anezhañ ent emgefre, hep e lañsañ.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Test diasur (flaky)","text":"Un test a dremen a-wechoù hag a c'hwit a-wechoù all hep abeg sklaer, ma ne c'haller ket fiziout ennañ da vat.","also":["flaky test","flaky tests","test diasur"]},{"id":"repro","g":"test","word":"Adc'hoarvezout (repro)","text":"Lakaat ur bug da c'hoarvezout en-dro a-ratozh en ur heuliañ ar memes pazennoù, evit gallout e studiañ hag e reizhañ. Skrivañ ar pazennoù-se eo al lodenn dalvoudusañ en un danevell bug.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Grevusted","text":"Pegen fall eo efed ur gudenn, eus un tamm trubuilh betek ma chom pep tra a-sav.","also":["severity","severity level","live grevusted"]},{"id":"deploy","g":"change","word":"Deploy","text":"Eilañ ur stumm nevez eus ar meziant war an urzhiataerioù a laka anezhañ en-dro, evel un eilskrid test pe ar servij enlinenn."},{"id":"release","g":"change","word":"Embannadenn","text":"Ur pakad labour echu gant un anv, a ya war-eeun asambles, gant notennoù berr war ar pezh a zo bet cheñchet. 🚀 Embannadennoù a skriv an notennoù diwar ar c'hartennoù echu.","also":["embannadennoù","release"]},{"id":"rollback","g":"change","word":"Distreiñ","text":"Distreiñ d'ar stumm diwezhañ a yae en-dro pa vez trubuilhoù gant unan nevez. En AI-gile e strollad Distreiñ ar pazennoù dizober skrivet war pep kemm en ur roll-gwiriañ hepken.","also":["distro","rollback","roll back"]},{"id":"live","g":"change","word":"War-eeun","text":"Ar stumm gwir a implij an dud, ha n'eo ket un eilenn evit amprouiñ traoù. An diorroerien a lavar ivez production (produadur).","also":["produadur","production","live"],"noTip":1},{"id":"change","g":"change","word":"Cheñchamant","text":"Ur cheñchamant steuniet war un dra a fiz an dud ennañ, skrivet da gentañ: petra, perak, ar riskl, pegoulz, ha penaos e zizober. Kregit gant unan gant 🔀 Sevel ur cheñchamant.","also":["cheñchamantoù","goulenn cheñchamant","change request"],"noTip":1},{"id":"risk","g":"change","word":"Riskl","text":"Un dra a c'hallfe mont a-dreuz, gant ur skor hervez pegen gwirheñvel ha pegen fall e vefe. ⚠️ Riskloù a zalc'h anezho en ur roll, ar skor uhelañ da gentañ, pep hini gant un deiziad evit adsellet.","also":["riskloù","marilh ar riskloù","risk"]},{"id":"chgwin","g":"change","word":"Prenestr cheñchamant","text":"Ar mareoù ma c'hall ar cheñchamantoù mont war-eeun, evel un abardaez sioul a Veurzh. E-maez ur prenestr ne c'haller ket echuiñ ur gartenn cheñchamant, nemet e vefe ur pres.","also":["prenestroù cheñchamant","change window"]},{"id":"gonogo","g":"change","word":"Mont / mont ket","text":"Ur gwiriadenn ziwezhañ just a-raok ma'z a ur c'hemm enlinenn: pep den a rank aprouiñ a lavar Go pe No go. Ne vez kendalc'het nemet pa lavar an holl Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Aprouadur","text":"Gortoz un ya a-raok ma krog al labour. Ur gartenn savet gant ur mignon, pe ur cheñchamant, a c'hortoz e ✅ Aprouadurioù betek ma vo aprouet pe nac'het ganeoc'h.","also":["aprouadurioù","approval"]},{"id":"quiettime","g":"change","word":"Mare sioul","text":"Ur prantad, evel e-pad ur skignañ war-eeun, un demo pe e-pad an noz, ma ne ya netra enlinenn. Ar skipailhoù a gendalc'h da labourat ha da destiñ, met ar mont enlinenn a c'hortoz betek ar fin. E lec'h all e vez anvet « change freeze ».","also":["mareoù sioul","skorn ar cheñchamantoù","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Un doare labourat ma labour ar re a sav ar meziant hag ar re a ra war-dro e vont en-dro evel ur skipailh hepken, gant kalz emgefreerezh, evit ma'z afe ar c'hemmoù enlinenn alies ha diarvar."},{"id":"cicd","g":"change","word":"CI/CD (enframmañ ha kas dalc'hmat)","text":"Kemmoù an holl a vez enframmet er stumm pennañ alies ha gwiriet ent emgefre bep tro (enframmañ dalc'hmat), evit ma vo ar meziant prest bepred da vont enlinenn en ur bouezañ war ur bouton (kas dalc'hmat).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Lakaat enlinenn dalc'hmat (continuous deployment)","text":"Ur bazenn pelloc'h eget ar c'has dalc'hmat: pep kemm a dremen ar gwiriadennoù a ya enlinenn anezhañ e-unan, hep bouton da bouezañ.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (korzenn)","text":"Ar steudad pazennoù emgefre a dremen ur c'hemm drezo a-raok mont enlinenn, evel build, test, ha goude deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Endro","text":"Un eilskrid a-part eus ar reizhiad evit ur pal resis, evel unan evit sevel, unan evit testiñ hag an hini enlinenn.","also":["environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Endro diorren","text":"An eilskrid ma labour un diorroer ennañ, alies war e urzhiataer, e-lec'h na ra droug da zen terriñ traoù.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"Endro test","text":"Un eilskrid a-part eus ar reizhiad implijet evit an testoù hepken, evit na vo ket stoket ouzh ar servij gwir.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"Staging (endro rakproduiñ)","text":"Un eilskrid diwezhañ aozet heñvel-poch ouzh an hini enlinenn, evit ur gwiriadenn ziwezhañ a-raok ma'z afe ur c'hemm enlinenn.","also":["staging environment","rakproduiñ"]},{"id":"artifact","g":"change","word":"Artefakt build","text":"Ar restr pe ar pakad a vez produet gant ur build, prest da vezañ miret, gwiriet pe lakaet enlinenn.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Ur reizhadenn vallus lakaet enlinenn buan, er-maez eus ar steuñv boaz, peogwir ez eus un dra pouezus torret.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch (pakad reizhañ)","text":"Un hizivadenn vihan a reizh ur bug pe a stank un toull surentez. Pouezus eo lakaat ar patchoù surentez buan.","also":["patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Niverenn stumm","text":"Ur skritell evel 2.4.1 a lavar peseurt embannadur hoc'h eus. Alies e cheñch an niver kentañ evit ar c'hemmoù bras hag an hini diwezhañ evit ar reizhadennoù bihan.","also":["version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Notennoù embannadur","text":"Ur roll berr ha sklaer eus ar pezh a zo bet kemmet en un embannadur, evit ar re a implij anezhañ, gant ar reizhadennoù hag ar bevennoù anavezet. Lavaret e vez ivez « changelog ».","also":["release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag (gwintenn arc'hwel)","text":"Un derc'her enaouiñ-lazhañ evit un arc'hwel, evit ma c'hallfe al labour nevez mont enlinenn kuzhet ha bezañ enaouet (pe lazhet en-dro) hep embannadur nevez.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Reizhañ un embannadur fall en ur lakaat buan ur stumm nevez reizhet e-lec'h distreiñ d'an hini kozh.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Embannadur kanari (canary)","text":"Lakaat ur c'hemm enlinenn evit ur strollad bihan da gentañ, ha evit an holl nemet pa seblant mont mat. Anvet diwar ar c'hanarioù a gase ar vengleuzierien dindan an douar da gemenn an droug abred.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Lakaat enlinenn glas-gwer (blue-green)","text":"Derc'hel daou eilskrid eus ar reizhiad enlinenn ha kas an dud war an hini nevez en un taol, evit gallout distreiñ diouzhtu mar ez a fall.","also":["blue-green","blue-green deployment","blue green deployment"]},{"id":"zerodown","g":"change","word":"Lakaat enlinenn hep arsav (zero-downtime)","text":"Lakaat ur stumm nevez enlinenn hep na chomfe ar servij a-sav ur wech ebet evit e implijerien.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Merañ ar c'hemmoù","text":"Sikour ar c'hemmoù da vont mat: pouezañ ar riskl, kaout an aotre a zere ha dibab ur mare mat. Lavaret e vez ivez « change management ».","also":["change enablement","change management","mererezh ar c'hemmoù"]},{"id":"cab","g":"change","word":"Kuzul ar c'hemmoù (CAB)","text":"Ur strollad a sell ouzh ar c'hemmoù pouezus hag a ziviz ha pegoulz e c'hallont bezañ graet.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Kemm standard","text":"Ur c'hemm dister e riskl graet bep tro gant ar memes doare amprouet mat, ma vez aotreet en a-raok.","also":["standard change","standard changes","kemmoù standard"]},{"id":"normchange","g":"change","word":"Kemm boutin","text":"Ur c'hemm a rank bezañ gwiriet hag aotreet a-raok bezañ graet.","also":["normal change","normal changes","kemmoù boutin"]},{"id":"emergchange","g":"change","word":"Kemm mallus","text":"Ur c'hemm a rank bezañ graet diouzhtu evit reizhañ pe evit mirout ouzh ur gudenn grevus, gant un aotre buanoc'h ivez.","also":["emergency change","emergency changes","kemmoù mallus"]},{"id":"automation","g":"change","word":"Emgefreerezh","text":"Lakaat an urzhiataer d'ober e-unan ul labour adarre hag adarre, evit ma vo graet buanoc'h hag en hevelep doare bep tro.","also":["automation","automated","emgefreañ"],"noTip":1},{"id":"infra","g":"change","word":"Frammadur (infrastructure)","text":"Ar mekanikoù, ar rouedadoù hag ar servijoù ma ya ar meziantoù en-dro warno.","also":["infrastructure","infra","frammadur"]},{"id":"iac","g":"change","word":"Frammadur e stumm kod (IaC)","text":"Deskrivañ ho servijerioù hag hoc'h arventennoù e restroù miret gant ar c'hod, evit gallout o adsevel heñvel-poch bep tro.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud (koumoul)","text":"Feurmiñ urzhiataerioù, lec'h-mirout ha servijoù digant ur pourvezer bras dre ar genrouedad, e-lec'h bezañ perc'henn war ar mekanikoù hoc'h-unan.","also":["cloud","the cloud","cloud computing","koumoul"]},{"id":"provider","g":"change","word":"Pourvezer cloud","text":"Un embregerezh a feurm galloud jediñ dre ar genrouedad, evel Amazon Web Services (AWS), Microsoft Azure pe Google Cloud.","also":["cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Herberc'hiañ (hosting)","text":"Al lec'h m'emañ hoc'h arload pe ho lec'hienn hag ez a en-dro, evit ma c'hallfe an dud tizhout anezhañ, feurmet digant un embregerezh peurliesañ.","also":["hosting"]},{"id":"domain","g":"change","word":"Anv domani","text":"Ar chomlec'h web a skriv an dud, evel example.com. E feurmiñ a rit bep bloaz, setu e rank bezañ adnevesaet.","also":["domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Berradur « domain name system »: levr chomlec'hioù ar genrouedad, a dro un anv evel example.com e chomlec'h an urzhiataer a zere.","also":["domain name system"]},{"id":"container","g":"change","word":"Kontener (container)","text":"Ur pakad serret ennañ un arload ha kement tra en deus ezhomm, evit ma'z afe en-dro en hevelep doare war forzh peseurt urzhiataer. Docker eo an ostilh brudetañ.","also":["container","containers","Docker","kontenerioù"],"noTip":1},{"id":"vm","g":"change","word":"Mekanik galloudel (VM)","text":"Un urzhiataer « ijinet » a ya en-dro e-barzh unan gwir, evit ma c'hallfe ur mekanik bras ober evel meur a hini.","also":["VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (hep servijer)","text":"Lakaat kod da vont en-dro hep ober war-dro servijer ebet hoc'h-unan: ar pourvezer a lañs anezhañ pa vez ezhomm ha paeañ a rit ar pezh a implijit."},{"id":"lb","g":"change","word":"Kempouezer karg (load balancer)","text":"Un dra a rann ar weladennerien etre meur a servijer, evit na vefe hini ebet beuzet.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"Krubuilh (cache)","text":"Ur stal dorn eus an disoc'hoù nevesañ miret tost, evit na vefe ret pellgargañ pe jediñ an hevelep tra en-dro. E skarzhañ a c'hall reizhañ pajennoù a seblant bezañ dispredet.","also":["cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Rouedad skignañ endalc'hadoù (CDN)","text":"Ur strollad servijerioù dre ar bed a-bezh a vir eilskridoù eus ho pajennoù hag eus ho skeudennoù tost d'ho kweladennerien, evit ma vefent karget buan.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Treuzkas (migration)","text":"Dilec'hiañ roadennoù pe reizhiadoù eus un aozadur kozh d'unan nevez, pe kemmañ gant evezh aozadur ur stlennvon.","also":["migration","migrations","database migration"]},{"id":"service","g":"run","word":"Servij","text":"Un dra savet ganeoc'h a fiz an dud ennañ, evel ul lec'hienn pe un arload, ha ma vez taolet evezh outañ evit ma kendalc'ho da vont en-dro. Merkit “Ur servijer eo ar raktres-mañ” ha lavarit petra a ginnig, piv a implij anezhañ ha piv a zo war-garg.","also":["servijoù","service"]},{"id":"uptimepct","g":"run","word":"Uptime (amzer en-dro)","text":"Pegement eus an amzer ez a ur servij en-dro, e dregantad peurliesañ. Gant 99,9 % e c'hall chom a-sav war-dro 43 munutenn bep miz c'hoazh.","also":["uptime","uptime percentage","amzer en-dro"]},{"id":"uptime","g":"run","word":"Gwiriadenn pad-labour","text":"Ur wiriadenn emgefreek, bep un nebeud munutennoù, e respont c'hoazh ho servij. Ma c'hwit meur a wech diouzh renk, AI-gile a zigor e-unan ur gartenn darvoud.","also":["uptime checks","uptime"]},{"id":"statuspage","g":"run","word":"Pajenn statud","text":"Ur bajenn foran a ziskouez hag-eñ ez a ur servij en-dro (gwer, orañjez pe ruz) gant ar c'heloù diwezhañ, evit ma c'hallfe an implijerien sellet e-lec'h goulenn.","also":["pajennoù statud","status page"]},{"id":"desk","g":"run","word":"Burev servij","text":"Al lec'h ma tegouezh goulennoù ha danevelloù an dud a implij ho servij. AI-gile a ren pep hini en ur goulenn, un darvoud pe ur soñj, hag a lavar pa seblant bezañ un dra bet danevellet dija.","also":["burevioù servij","burev skoazell","skoazell"]},{"id":"svcrequest","g":"run","word":"Goulenn servij","text":"Unan bennak a c'houlenn un dra boutin, evel ur gont nevez pe un tamm skoazell, e-lec'h lavaret ez eo torret un dra. Gortoz a ra e dro; an darvoud a dremen da gentañ.","also":["goulennoù servij"]},{"id":"incident","g":"run","word":"Darvoud","text":"Un dra torret pe na ya ket en-dro mat evit an dud a implij anezhañ bremañ, evel al lec'hienn a-sav pe gorrek-tre. Ur gartenn darvoud 🔥 a dremen a-raok an holl re all: adlakaat an traoù en-dro a zeu da gentañ.","also":["darvoudoù","incident"]},{"id":"major","g":"run","word":"Darvoud bras","text":"Un darvoud bras: kalz tud tizhet, pe arc'hant pe roadennoù e riskl. Ur bouton a laka an holl skipailhoù warnañ (strollad), a zihun an hini a zo war-garg hag a c'houlenn un nevesadenn statud bep 30 munutenn.","also":["darvoudoù bras","dramm bras","major incident"]},{"id":"oncall","g":"run","word":"War-garg","text":"Bezañ an hini a respont pa dorr un dra, zoken en noz. Pep servij en deus un ezel eus ar skipailh war-garg, dihunet da gentañ evit e zarvoudoù.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Eur respont","text":"Pegeit e c'hall ur gartenn gortoz ur respont kentañ, da skouer un eurvezh evit un darvoud. Goude-se e kav un horolaj ruz, evit na vefe ankouaet netra didrouz. Graet e vez pal respont anezhañ ivez.","also":["eurioù respont","pal respont","response target"]},{"id":"postmortem","g":"run","word":"Dielfennadenn goude an darvoud","text":"Ur sell berr war-dreñv goude un darvoud: petra a zo c'hoarvezet, petra en deus sikouret ha petra cheñch, hep tamall den ebet. Ne c'haller ket serriñ un darvoud hep unan.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Kudenn","text":"An abeg kuzh a-dreñv un darvoud pe meur a hini. Ur gartenn 🧩 kudenn a strollad an darvoudoù a zistro atav, evit kavout an abeg ha reizhañ anezhañ da vat.","also":["kudennoù","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Gwir abeg","text":"An abeg gwir ma'z eo torret un dra, ha n'eo ket hepken ar pezh ho peus gwelet o vont a-dreuz. Reizhit ar gwir abeg ha ne zistro ket ken an darvoud.","also":["gwir abegoù","root cause"]},{"id":"workaround","g":"run","word":"Diskoulm a-vremañ","text":"Un doare da virout an traoù en-dro betek ma vo prest ar gwir reizhadenn, evel adloc'hañ un dra pa chom sac'het. Skrivet e vez war ar gartenn kudenn evit na vefe ret da zen e gavout en-dro.","also":["diskoulmoù a-vremañ","workaround"]},{"id":"knownerror","g":"run","word":"Fazi anavezet","text":"Ur gudenn ma'z eo anavezet he abeg met n'eo ket reizhet c'hoazh, gant un dro-dro skrivet peurliesañ. 🧩 Fazioù anavezet a ro ar roll anezho, evit ma implijfe an holl an dro-dro e-lec'h klask en-dro.","also":["fazioù anavezet","known error"]},{"id":"runbook","g":"run","word":"Levr-kuzul","text":"Kemennadurioù pazenn ha pazenn evit reizhañ ur seurt trubuilh anavezet, evit ma vefe graet en hevelep doare, buan, bep tro. Goude un darvoud bras e c'hall ar skipailh kinnig unan deoc'h da aprouiñ.","also":["levrioù-kuzul","runbook"]},{"id":"ci","g":"run","word":"Elfenn kefluniadur","text":"Un dra a zo ezhomm d'ho servij, evel ur servijer, un domani, un testeni, un alc'hwez pe ur pourvezer. 🗂️ Elfennoù kefluniadur a ro anezho evit pep servij, evit ma welfec'h petra a vez tizhet gant un darvoud ha petra a zo da nevesaat pe da eilenniñ.","also":["elfennoù kefluniadur"]},{"id":"expiry","g":"run","word":"Deiziad termen","text":"An deiziad ma paouez un dra da vont en-dro nemet e vefe adnevesaet, evel testeni surentez ul lec'hienn pe he chomlec'h web. AI-gile a evezh an deiziadoù-se hag a ra ur gartenn evit adnevesaat pep hini 30 deiz a-raok, evit na chomfe netra a-sav dre souezh.","also":["deiziadoù termen","termen","evezh an termen"]},{"id":"backup","g":"run","word":"Eilenn surentez","text":"Un eilenn eus ho roadennoù enrollet a-raok, evit en em dennañ ma vez kollet pe gwastet un dra. AI-gile a ra un eilenn surentez eus ho taolennoù bemdez.","also":["eilennoù surentez","backup"]},{"id":"restore","g":"run","word":"Assav","text":"Lakaat roadennoù en-dro diwar un eilenn surentez. N'eo talvoudus da vat un eilenn surentez nemet pa ouzit e c'haller assevel anezhi, setu e talv ar boan he amprouiñ a-wechoù.","also":["assavet","restore"]},{"id":"svcreview","g":"run","word":"Adwelet ar servij","text":"Ur sell war-dreñv war ur miz eus ur servij: darvoudoù digoret ha reizhet, pegen buan o deus bet respont an dud, pad-labour ha tokenoù implijet. Adwelet ar miz a ziskouez se evit pep servij.","also":["adweladennoù servij","adwelet ar miz","adweladennoù miziek"]},{"id":"accessreview","g":"run","word":"Adwelet an enaouiñ","text":"Gwiriañ bep 90 deiz piv a c'hall mont e-barzh c'hoazh: al liammoù rannañ, rolloù ar vignoned hag ar gerioù-tremen hag an alc'hwezioù enrollet. Mirout pe lemel a rit pep hini, evit na chomfe ket monedoù kozh a-zispont.","also":["adweladennoù an enaouiñ"]},{"id":"improvements","g":"run","word":"Roll ar gwellaadennoù","text":"Kement tra en deus divizet ar skipailh gwellaat, en ul lec'h hepken: kinnigoù ar sell war-geñver, oberoù an adweladennoù ha reizhadennoù ar c'hudennoù, pep hini gant e statud. E gavout a rit e 📈 Gwellaadennoù.","also":["rolloù gwellaadennoù","gwellaadennoù"]},{"id":"tokencap","g":"run","word":"Bevenn tokenoù","text":"Ur vevenn viziek war an tokenoù a c'hall implijout ajanted ur servij. Da 80% e resevit ur c'hemenn diwall; da 100% e chom o labour a-dreñv da c'hortoz betek ar miz war-lerc'h pe betek ma sav ac'hanoc'h ar vevenn.","also":["bevennoù tokenoù"]},{"id":"svcmgmt","g":"run","word":"Merañ ar servijoù","text":"Kement tra a zo ret evit derc'hel ur servij talvoudus hag en-dro evit ar re a gont warnañ, deiz goude deiz.","also":["service management","mererezh servijoù"]},{"id":"itil","g":"run","word":"ITIL","text":"Ur sturlevr implijet a-leizh evit merañ mat ar servijoù, a ra war-dro traoù evel an darvoudoù, ar c'hudennoù hag ar c'hemmoù. An anv a dalveze gwechall IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Merañ ar servijoù TI (ITSM)","text":"Kinnig an teknologiezh evel ur servij evit an dud, gant doareoù sklaer da blediñ gant ar goulennoù, an darvoudoù, ar c'hemmoù hag ar gwellaennoù.","also":["ITSM","IT service management","merañ servijoù TI"]},{"id":"managed","g":"run","word":"Servij meret","text":"Ur servij a vez lakaet en-dro ha kempennet evidoc'h gant unan all, hervez un emglev diwar-benn pegen mat e rank mont en-dro.","also":["managed service","managed services","servijoù meret"]},{"id":"svcowner","g":"run","word":"Perc'henn ar servij","text":"An den a respont eus ur servij en e bezh: pegen mat ez a en-dro, pegement e koust ha penaos e vez gwellaet.","also":["service owner","service owners"]},{"id":"sla","g":"run","word":"Emglev live servij (SLA)","text":"Ur bromesa skrivet d'ar c'hliantoù diwar-benn pegen mat ez aio ur servij en-dro, evel « en-dro 99,9 % eus an amzer » pe « respont a-benn un eur », alies gant arc'hant distaolet ma ne vez ket doujet.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Pal live servij (SLO)","text":"Pal ar skipailh e-unan evit pegen mat e tlefe ur servij mont en-dro e-pad ur prantad, lakaet un tammig strishoc'h eget ar SLA peurliesañ, evit bezañ war an diogel.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Meneger live servij (SLI)","text":"Ar muzul gwir a geñveriit gant ur pal, evel ar c'hementad gweladennoù a zo bet karget mat.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Hegerzhded","text":"Ha gallout a ra an dud implijout ur servij pa o deus ezhomm, muzuliet alies dre an uptime.","also":["availability","high availability"]},{"id":"downtime","g":"run","word":"Amzer arsav (downtime)","text":"An amzer ma ne ya ket ur servij en-dro pe ma vez lazhet, steuñvet pe get.","also":["downtime","down time","arsav"]},{"id":"errorbudget","g":"run","word":"Budjed fazioù","text":"Ar c'hementad bihan a fazioù a vez aotreet gant ho pal fiziusted. Keit ha ma chom un tamm, e c'hallit riskañ kemmoù; pa vez implijet penn-da-benn, e rankit gorrekaat.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Troc'h servij (outage)","text":"Ur mare ma'z eo ur servij a-sav pe torret-mik evit e implijerien.","also":["outage","outages","troc'hoù servij"]},{"id":"degraded","g":"run","word":"Diskaret","text":"En-dro, met fall: gorrek, pe gant lodennoù na'z eont ket en-dro.","also":["degraded","degraded service","servij diskaret"]},{"id":"monitoring","g":"run","word":"Evezhiañ (monitoring)","text":"Evezhiañ ur servij ent emgefre hep paouez, evit merzout ar c'hudennoù, ar gwellañ a-raok ma vint merzet gant an implijerien.","also":["monitoring"]},{"id":"observability","g":"run","word":"Arselladusted (observability)","text":"Pegen mat e c'hallit gouzout petra a c'hoarvez e-barzh ur reizhiad diouzh an diavaez, gant e logoù, e niverennoù hag e roudoù.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Log (marilh)","text":"Un deizlevr a zalc'h ur programm a-hed an amzer eus ar pezh a ra, implijet evit kompren petra a zo aet a-dreuz.","also":["logs","logging","marilh"],"noTip":1},{"id":"trace","g":"run","word":"Roud (trace)","text":"Un enrolladenn eus an hent a ra ur goulenn dre lodennoù disheñvel ur reizhiad, pazenn ha pazenn, o tiskouez pelec'h eo bet gorrekaet.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Dale (latency)","text":"Pegeit e pad a-raok ma respont un dra, evel ar gortoz etre ar c'hlik ha ma teu ar bajenn war wel.","also":["latency"]},{"id":"alert","g":"run","word":"Galv-diwall (alert)","text":"Ur gemennadenn emgefre a lavar ez eus ezhomm da ober van ouzh un dra, evel al lec'hienn na respont ket ken.","also":["alert","alerts","alerting","galvoù-diwall"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Skuizhder galvoù-diwall","text":"Pa'z eus kement a c'halvoù-diwall ma krog an dud d'o leuskel a-gostez, ar re bouezus ivez.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Taolenn-stur (dashboard)","text":"Ur skramm a ziskouez en ur sell an niverennoù hag ar stadoù pouezusañ.","also":["dashboard","dashboards","taolenn-stur"],"noTip":1},{"id":"paging","g":"run","word":"Paging (galv prim)","text":"Galv pe dihuniñ en un taol prim an den e gward diwar-benn ur gudenn.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Kas pelloc'h (escalation)","text":"Galv unan gant muioc'h a ampartiz pe a veli pa ne c'haller ket diskoulmañ ur gudenn el live m'emañ, pe ket buan a-walc'h.","also":["escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Triage (didriañ)","text":"Didriañ buan ar c'hudennoù a zegouezh hervez pegen mallus ha pegen pouezus int, evit ma vo graet war-dro ar re washañ da gentañ.","also":["triaged","didriañ"]},{"id":"impact","g":"run","word":"Efed (impact)","text":"Pegement e tizh un dra an dud: pet anezho, ha pegen fall.","noTip":1},{"id":"urgency","g":"run","word":"Mall","text":"Pegen buan eo ret plediñ gant un dra. An efed hag ar mall asambles a ziviz ar gentelezh.","noTip":1},{"id":"plevels","g":"run","word":"Liveoù kentelezh (P1, P2…)","text":"Skritelloù evit lavarout pegen mallus eo ur gudenn. P1 eo ar grevusañ ha ret eo ober diouzhtu.","also":["P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"Lostad tikedoù","text":"Roll ar goulennoù hag an darvoudoù a c'hortoz bezañ kemeret.","also":["ticket queue","ticket queues","lostad"]},{"id":"tiers","g":"run","word":"Linenn gentañ hag eil linenn","text":"Liveoù skoazell: al linenn gentañ a gemer ar galv hag a reizh an traoù simpl; an eil linenn he deus barregezhioù donoc'h evit ar re ziaesoc'h. Lavaret e vez ivez tier 1 ha tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Rener an darvoud","text":"An den nemetañ a ren ar respont d'un darvoud, evit ma ouife an holl piv a ziviz ha piv a ra petra.","also":["incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Amzer respont","text":"Pegeit e pad a-raok ma vez kemeret ur goulenn pe un darvoud evit ar wech kentañ.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Amzer diskoulmañ","text":"Pegeit e pad diskoulmañ penn-da-benn ur goulenn pe un darvoud, adalek ma vez meneget betek ma vez reizhet.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Amzer adsevel keitat (MTTR)","text":"E keitat, pegeit e pad lakaat ur servij en-dro goude ma'z eo torret. MTTR a c'hall talvezout traoù un tammig disheñvel, neuze lavarit petra a vuzuliit.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Amzer keitat etre an torradurioù (MTBF)","text":"E keitat, pegeit ez a ur servij en-dro a-raok ma torr un dra bennak.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Stlennvon ar c'hefluniadur (CMDB)","text":"Roll an holl elfennoù kefluniadur hag an doare ma'z int liammet, evit gwelet petra a zalc'h diouzh petra.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Madoù (asset)","text":"Kement tra a dalvoudegezh a zo deoc'h pe a baeit evit lakaat ar servij en-dro, evel un urzhiataer hezoug, ul lañvaz meziant pe un domani.","also":["asset","assets","mad"],"noTip":1},{"id":"capplan","g":"run","word":"Steuñviñ ar varregezh","text":"Bezañ sur e vo a-walc'h a c'halloud jediñ, a lec'h-mirout hag a dud evit ar pezh a zo o tont.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Kreskiñ ar varregezh (scaling)","text":"Plediñ gant muioc'h a implijerien en ur reiñ muioc'h a c'halloud d'ur mekanik (scale up) pe en ur ouzhpennañ mekanikoù all (scale out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Kenderc'hel an obererezh","text":"Steuñvioù evit lakaat an traoù pouezus da genderc'hel pa'z a un dra bras a-dreuz, evel koll ur burev, ur pourvezer pennañ pe an urzhiataerioù.","also":["business continuity","business continuity plan","steuñv kenderc'hel"]},{"id":"dr","g":"run","word":"Adsevel goude ur reuz (DR)","text":"Ar steuñv hag an ostilhoù evit adlakaat ur servij en-dro goude un dra grevus, evel koll ur greizenn roadennoù a-bezh.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Pal amzer adsevel (RTO)","text":"An amzer hirañ ma c'hall ur servij chom a-sav goude ur reuz a-raok ma rank mont en-dro adarre.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Pal poent adsevel (RPO)","text":"Pegement a roadennoù nevez a c'hallfec'h koll, muzuliet e amzer. Un RPO a un eur a dalvez eilennoù surentez bep eur da nebeutañ.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Doubladur (redundancy)","text":"Kaout traoù a-gostez prest, evel un eil servijer, evit na zistrujfe ket un torr hepken ar servij.","also":["redundancy","doubladur"]},{"id":"failover","g":"run","word":"Failover (tremen d'ar sikour)","text":"Tremen e-unan d'ur reizhiad sikour pa c'hwit an hini boas.","also":["fail over","failover"]},{"id":"spof","g":"run","word":"Poent torr nemetañ (SPOF)","text":"Ul lodenn hepken a laka pep tra da gouezhañ ganti pa dorr, peogwir n'eus netra ebet en he lec'h.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Prenestr kempenn","text":"Ur mare steuñvet ma c'hall ur servij bezañ ehanet pe gorrek evit e gempenn, kemennet d'an implijerien en a-raok.","also":["maintenance window","maintenance windows","planned maintenance","kempenn steuñvet"]},{"id":"handover","g":"run","word":"Treuzkas (handover)","text":"Treuzkas al labour, ar ouiziegezh hag ar garg d'un den pe d'ur skipailh all, evit na vo netra ankouaet.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Diaz gouiziegezh","text":"Un dastumad pennadoù skoazell ha respontoù, evit an implijerien hag evit ar skipailh.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Plijadur ar c'hliantoù (CSAT)","text":"Un notenn roet gant an implijerien evit lavarout pegen laouen int bet, goulennet alies goude ma'z eo bet serret ur goulenn.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Pourvezer","text":"Un embregerezh diavaez a gontit warnañ, evel ho herberc'hier. Lavaret e vez ivez « vendor » pe « third party ».","also":["supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Lemel ur servij kuit","text":"Lazhañ ur servij da viken, en un doare diarvar: kemenn d'e implijerien, plediñ gant e roadennoù hag e voned, ha paouez gant e goustoù.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Dibenn buhez (EOL)","text":"Pa ne vez ket ken hizivadennoù pe skoazell digant ar saver evit ur produ, ha neuze e tlefe bezañ erlec'hiet.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Kibersurentez","text":"Gwareziñ ar reizhiadoù hag ar roadennoù ouzh an torridigezhioù, al laeradennoù hag an noazoù.","also":["cybersecurity","cyber security","surentez niverel"]},{"id":"authn","g":"sec","word":"Dilesadur (authentication)","text":"Gwiriañ piv eo unan bennak, gant ur ger-tremen pe ur c'hod peurliesañ. Berraet alies e « authn ».","also":["authentication","authn","dilesañ"]},{"id":"authz","g":"sec","word":"Aotreadur (authorisation)","text":"Gwiriañ petra en deus unan bennak ar gwir d'ober, pa ouzer piv eo. Berraet alies e « authz ».","also":["authorisation","authz","authorization"]},{"id":"mfa","g":"sec","word":"Dilesadur lieselfenn (MFA)","text":"Kevreañ gant div brouenn pe muioc'h, evel ur ger-tremen hag ur c'hod war ho pellgomzer. Lavaret e vez ivez « dilesadur div elfenn » (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","dilesadur div elfenn"]},{"id":"sso","g":"sec","word":"Kevreañ unel (SSO)","text":"Kevreañ ur wech hepken evit mont e meur a reizhiad, evel implijout ho kont labour e pep lec'h.","also":["SSO","single sign-on","kevreañ unel"]},{"id":"pwmgr","g":"sec","word":"Merour gerioù-tremen","text":"Un arload a grou gerioù-tremen kreñv hag a zalc'h soñj anezho evidoc'h.","also":["password manager","password managers","merour gerioù-tremen"]},{"id":"secret","g":"sec","word":"Kuzhadenn (secret)","text":"Ur ger-tremen, un alc'hwez pe ur c'hod prevez all a implij ur programm evit mont e-barzh un dra bennak. Biskoazh ne rank bezañ rannet na skrivet er c'hod.","also":["secret","secrets","kuzhadennoù"],"noTip":1},{"id":"apikey","g":"sec","word":"Alc'hwez API","text":"Ur c'hod kuzh a ro an tu d'ur programm da implijout API ur servij all, hag a ziskouez piv en implij (hag a bae evitañ).","also":["API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Token moned (access token)","text":"Un aotre-tremen padennek a brouv ez eo aotreet ur programm da vont e-barzh, evit na vefe ket ezhomm eus ho ker-tremen bep tro. N'eo ket an hevelep tra hag un token AI.","also":["access token","access tokens","token moned"]},{"id":"encryption","g":"sec","word":"Enrinegañ (encryption)","text":"Meskañ an titouroù evit na c'hallfe nemet an hini en deus an alc'hwez mat o lenn.","also":["encryption","encrypted","encrypt","enrinegadur","enrineget"]},{"id":"https","g":"sec","word":"HTTPS","text":"An doare diarvar ma tremen ar pajennoù web, merket gant ar potailh en ho merdeer, evit na c'hallfe den etre an daou o lenn nag o c'hemmañ."},{"id":"cert","g":"sec","word":"Testeni SSL/TLS","text":"Ur gartenn-anaout niverel a ro an tu d'ul lec'hienn da brouiñ piv eo ha da implijout HTTPS. Diamzeriñ a ra, setu e rank bezañ adnevesaet.","also":["TLS certificate","SSL certificate","certificate","certificates","testeni"]},{"id":"permissions","g":"sec","word":"Aotreoù","text":"Ar reolennoù a lavar piv a c'hall gwelet pe kemmañ petra.","also":["permission","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Gwirioù bihanañ (least privilege)","text":"Reiñ da bep den pe programm ar moned en deus ezhomm da vat hepken, ha keit ha m'en deus ezhomm hepken.","also":["least privilege","principle of least privilege","gwirioù bihanañ"]},{"id":"rbac","g":"sec","word":"Kontroll ar moned dre rollioù (RBAC)","text":"Reiñ ar moned hervez ar roll, evel lenner pe embanner, kentoc'h eget den ha den.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Bresk (vulnerability)","text":"Ur wander a c'hallfe unan bennak implijout evit en em silañ e-barzh pe ober droug.","also":["vulnerability","vulnerabilities","breskted","gwander"]},{"id":"zeroday","g":"sec","word":"Zero-day (bresk deiz zero)","text":"Ur wander anavezet gant an argaderien a-raok m'o defe bet ar saverien amzer ebet d'he reizhañ.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Drougveziant (malware)","text":"Meziant noazus, evel ar viruzoù, savet evit gwastañ, spiañ pe laerezh.","also":["malware","meziant droukyoulek"]},{"id":"ransomware","g":"sec","word":"Ransomware (drougveziant dasprenañ)","text":"Un drougveziant a sparl ho restroù hag a c'houlenn arc'hant evit o dizalc'hañ. Eilennoù surentez mat eo ar gwarez gwellañ.","also":["ransomware attack","dasprenañ"]},{"id":"phishing","g":"sec","word":"Higennañ (phishing)","text":"Kemennadennoù faos a glask ho touellañ evit ma rofec'h gerioù-tremen pe arc'hant, pe ma tigorfec'h un dra noazus.","also":["phishing","phishing email","phishing emails","higennañ"]},{"id":"socialeng","g":"sec","word":"Ijinerezh sokial (social engineering)","text":"Touellañ an dud, ha n'eo ket an urzhiataerioù, evit kaout ur moned, evel ur galv faos a-berzh « skoazell an informatik »."},{"id":"firewall","g":"sec","word":"Moger-dan (firewall)","text":"Ur gward a ziviz peseurt tremenerezh rouedad a c'hall dont e-barzh pe mont er-maez.","also":["firewall","firewalls","moger-dan"]},{"id":"vpn","g":"sec","word":"VPN (rouedad prevez galloudel)","text":"Berradur « virtual private network »: ul liamm prevez hag enrineget dre ar genrouedad, implijet alies evit tizhout reizhiadoù al labour en un doare diarvar.","also":["virtual private network","rouedad prevez galloudel"]},{"id":"ddos","g":"sec","word":"Nac'hañ servij (DoS, DDoS)","text":"Beuziñ ur servij dindan kement a dremenerezh faos ma ne c'hall ket an dud wir e implijout ken. DDoS a dalvez e teu eus kalz urzhiataerioù war un dro.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Test treantiñ (pen test)","text":"Gopraat arbennigourien a-du ganeoc'h evit klask en em silañ e-barzh, evit ma vo kavet ar gwanderioù a-raok an argaderien wir.","also":["pen test","pen testing","penetration testing","pentest","test treantiñ"]},{"id":"audit","g":"sec","word":"Aodit surentez","text":"Ur gwiriadenn aketus eus pegen mat eo gwarezet un dra, e-keñver ur roll boazioù mat.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Patromiñ ar gourdrouzoù","text":"Prederiañ piv a c'hallfe argadiñ un dra, penaos, ha petra a rafec'h evit mirout outañ.","also":["threat modelling","threat model","threat modeling","gourdrouz"]},{"id":"breach","g":"sec","word":"Torridigezh roadennoù (data breach)","text":"Pa'z a titouroù prevez etre daouarn tud na zlefent ket o c'haout, pe pa vezont kollet pe kemmet hep aotre.","also":["data breach","data breaches","diskuliadenn roadennoù"]},{"id":"pii","g":"sec","word":"Roadennoù personel","text":"Kement titour diwar-benn un den a c'haller anavezout, evel un anv, ur chomlec'h postel pe ul lec'hiadur. Lavaret e vez ivez PII.","also":["personal data","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR (RGPD)","text":"Lezenn Europa war ar roadennoù personel (ar Rouantelezh-Unanet he deus he stumm dezhi): dastumit ar pezh hoc'h eus ezhomm hepken, mirit anezhañ en diogel, ha lezit an dud da welet pe da ziverkañ o re.","also":["General Data Protection Regulation","RGPD"]},{"id":"dataprot","g":"sec","word":"Gwarez ar roadennoù","text":"Ober war-dro ar roadennoù personel evel ma zere hag hervez al lezenn.","also":["data protection","data protection law","gwarez ar roadennoù"]},{"id":"privacypolicy","g":"sec","word":"Politikerezh prevezded","text":"Ur bajenn foran a lavar peseurt roadennoù personel a zastumit, perak, ha petra a rit ganto.","also":["privacy policy","privacy statement","privacy notice","prevezded"]},{"id":"consent","g":"sec","word":"Asant (consent)","text":"Ur « ya » sklaer ha dieub roet gant un den evit ma vo implijet e roadennoù en un doare resis. Gallout a ra e dennañ en-dro pa gar.","also":["consent","opt-in","asant"],"noTip":1},{"id":"cookie","g":"sec","word":"Toupin (cookie)","text":"Ur restr vihan a enroll ul lec'hienn en ho merdeer evit derc'hel soñj eus traoù, evel ez oc'h kevreet. Evit lod e rank ho asant bezañ goulennet da gentañ.","also":["cookie","cookies","toupinoù"],"noTip":1},{"id":"minimisation","g":"sec","word":"Bihanaat ar roadennoù","text":"Dastum ha mirout ar roadennoù personel hoc'h eus ezhomm da vat evit al labour hepken.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Mirout ar roadennoù","text":"Pegeit e vez miret ar roadennoù a-raok bezañ diverket. Mirout anezho ket pelloc'h eget ret a zo diogeloc'h, hag alies eo goulennet gant al lezenn.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"Dizanvekaat (anonymisation)","text":"Kemmañ ar roadennoù evit na c'hallfe den bezañ anavezet diouto ken, en un doare poellek.","also":["anonymisation","anonymised","anonymization","anonymous data","dizanv"]},{"id":"pseudo","g":"sec","word":"Lesanvekaat (pseudonymisation)","text":"Lakaat kodoù e-lec'h an anvioù hag ar munudoù all, gant un alc'hwez miret a-part evit o liammañ en-dro. Roadennoù personel int c'hoazh.","also":["pseudonymisation","pseudonymised","pseudonymization","lesanv"]},{"id":"dpa","g":"sec","word":"Emglev plediñ gant ar roadennoù (DPA)","text":"Ur gevrat a lavar penaos e c'hall ur pourvezer plediñ gant roadennoù personel en hoc'h anv.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Priziadenn efed war warez ar roadennoù (DPIA)","text":"Ur sell aketus, a-raok kregiñ, ouzh an doare ma c'hallfe ur raktres implijout roadennoù personel tizhout an dud, ha penaos digreskiñ ar riskloù.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Marilh aodit (audit log)","text":"Un enrolladenn eus piv en deus graet petra ha pegoulz, evit gallout gwiriañ an oberoù diwezhatoc'h.","also":["audit log","audit logs","audit trail","marilh aodit"]},{"id":"compliance","g":"sec","word":"Kenfurmded (compliance)","text":"Heuliañ al lezennoù, ar reolennoù hag ar standardoù a sell ouzhoc'h, ha gallout diskouez ez it diouto.","also":["compliance","compliant","kenfurm"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Ur standard etrebroadel brudet evit merañ surentez an titouroù. An embregerezhioù a c'hall bezañ testeniet diouzh e reolennoù.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Un danevell eus ar Stadoù-Unanet, gwiriet gant aoditerien diavaez, a ziskouez e ra un embregerezh war-dro roadennoù e c'hliantoù evel ma zere.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Un AI a labour e-unan war ur gefridi: lenn a ra ar c'hod, kemmañ a ra traoù, lañsañ a ra gwiriadennoù hag e ro keloù goude. Gwiriet e vez e labour memes tra.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"An tammoùigoù testenn a lenn hag a skriv un AI, war-dro tri c'hard ger pep hini. Implij an AI a vez kontet e tokenoù, neuze gant nebeutoc'h a dokenoù e chom muioc'h eus ho steuñvenn.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Un urzh bihan a ya en-dro e-unan d'ur mare termenet, da skouer pa grog un dalc'h AI, evit ma klevfe ar skipailh hoc'h evezhiadennoù.","also":["hooks"]},{"id":"ai","g":"ai","word":"Speredegezh artifisiel (AI)","text":"Reizhiadoù urzhiataer a ra traoù a soñj deomp e rankfe un den ober, evel skrivañ, respont da c'houlennoù pe anavezout skeudennoù.","also":["AI","artificial intelligence","speredegezh artifisiel","IA"],"noTip":1},{"id":"ml","g":"ai","word":"Deskiñ emgefre (ML)","text":"Un doare da lakaat an urzhiataerioù da zeskiñ patromoù diwar kalz skouerioù, e-lec'h reiñ reolennoù resis dezho.","also":["ML","machine learning","deskiñ emgefre"]},{"id":"model","g":"ai","word":"Model","text":"« Empenn » stummet ur reizhiad AI, savet en ur zeskiñ diwar ur bern skouerioù. Disheñvel eo ar modeloù a-fet barregezh, tizh ha priz.","also":["models","AI model","modeloù"],"noTip":1},{"id":"llm","g":"ai","word":"Model yezh bras (LLM)","text":"Ur model AI stummet diwar ur bern testennoù, evit ma c'hallfe lenn ha skrivañ ur yezh.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"AI genel (generative AI)","text":"AI a grou traoù nevez, evel testennoù, skeudennoù pe kod, ha n'eo ket hepken o renkañ pe oc'h anavezout anezho.","also":["GenAI","generative AI","AI genel"]},{"id":"chatbot","g":"ai","word":"Chatbot (robot-kaozeal)","text":"Ur programm a gomzit gantañ er yezh pemdez, o skrivañ pe o komz.","also":["chatbots","robot-kaozeal"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Ar pezh a roit d'un AI: ho koulenn pe hoc'h urzhioù, ha kement tra a roit dezhañ ouzhpenn. Gant promptoù sklaeroc'h e vez kavet respontoù gwelloc'h peurliesañ.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Ar ouiziegezh da skrivañ promptoù a ro disoc'hoù talvoudus ha fizius."},{"id":"sysprompt","g":"ai","word":"Prompt reizhiad","text":"Urzhioù a-dreñv ar c'hleuz a resev un AI a-raok ma krog ar gaoz, a ziviz e roll hag e reolennoù. Pouezusoc'h int eget ar pezh a skrivit.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Kendestenn (context)","text":"Kement tra a c'hall an AI gwelet e-pad ma labour: an urzhioù, ho kemennadennoù, ar restroù en deus lennet hag ar respontoù a-raok.","noTip":1},{"id":"ctxwin","g":"ai","word":"Prenestr kendestenn (context window)","text":"Pegement a c'hall un AI derc'hel en e spered war un dro, muzuliet e tokenoù. En tu all da se, al lodennoù koshañ a vez lamet pe berraet.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Dalc'h (session)","text":"Ur gaoz labour gant un AI, eus he fenn-kentañ d'he dibenn. Un dalc'h nevez a grog gant ur memor nevez-flamm.","also":["session","sessions","dalc'hioù"],"noTip":1},{"id":"memory","g":"ai","word":"Memor","text":"Notennoù a vir un AI etre an dalc'hioù, evit derc'hel soñj eus ho tibaboù hag eus an divizoù kent.","noTip":1},{"id":"hallucination","g":"ai","word":"Alfoadenn (hallucination)","text":"Pa lavar un AI un dra gant fiziañs met hep diazez pe faos. Gwiriit an traoù pouezus.","also":["hallucination","hallucinations","hallucinate","hallucinates","alfoadenn"]},{"id":"training","g":"ai","word":"Stummañ (training)","text":"Deskiñ ur model en ur ziskouez dezhañ ur bern skouerioù, a-raok ma vez implijet gant den.","also":["training","trained","stummadur"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Roadennoù stummañ","text":"Ar skouerioù en deus desket ur model diwarno. E ouiziegezh a ehan d'an deiziad ma voe dastumet ar roadennoù-se.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Bevenn ar ouiziegezh (knowledge cutoff)","text":"An deiziad ma echu ar ouiziegezh diabarzh un AI. Ne ouezo ket an traoù diwezhatoc'h, nemet ma klask anezho.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning (resisaat)","text":"Stummañ ouzhpenn ur model a zo anezhañ endeo gant ho skouerioù deoc'h, evit ma vo gwelloc'h evit ul labour resis.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference (implij ar model)","text":"Ur model AI implijet da vat evit respont d'un dra, d'ober an diforc'h gant e stummañ.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"Implij ostilhoù (tool use)","text":"Un AI a c'hall ober traoù, ha n'eo ket hepken komz: lañsañ urzhioù, lenn restroù pe klask war ar web, dre an ostilhoù a ro an arload dezhañ.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Isajant","text":"Un AI skoazell a ro un AI pennañ ul labour bihanoc'h dezhañ, hag a zegas an disoc'h en-dro.","also":["subagents","sub-agent","isajantoù"]},{"id":"multiagent","g":"ai","word":"Liesajant (multi-agent)","text":"Meur a AI o labourat asambles war ar memes tamm labour, pep hini gant e lodenn, evel ur skipailh bihan.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Emrenerezh (autonomy)","text":"Pegement a c'hall un AI ober anezhañ e-unan a-raok ma rank goulenn digant un den.","also":["autonomy","autonomous","emren"]},{"id":"hitl","g":"ai","word":"Un den er c'helc'h (human in the loop)","text":"Mirout un den en afer evit gwiriañ pe aprouiñ ar pezh a ra an AI er poentoù pouezus. En AI-gile, c'hwi eo.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Kael-surentez (guardrails)","text":"Bevennoù ha gwiriadennoù a vir oberoù un AI diarvar, evel ezhomm un aotre a-raok ma'z a tra pe dra enlinenn. Digreskiñ a reont risk ar fazioù, met ne lamont ket anezho a-grenn.","also":["guardrails","guardrail","kaelioù-surentez"]},{"id":"rag","g":"ai","word":"Genel kreñvaet gant klask (RAG)","text":"Lezel un AI da glask traoù en ho teulioù deoc'h a-raok respont, evit ma vo diazezet e respontoù war ho fedoù.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (enkorfadur)","text":"Treiñ un destenn en ur roll niverennoù a zalc'h he ster, evit ma c'hallfe un urzhiataer kavout traoù o deus ur ster tost.","also":["embeddings","enkorfadur"]},{"id":"vectordb","g":"ai","word":"Stlennvon vektorel","text":"Ur stlennvon savet evit klask er rolloù niverennoù-se (embeddings), evit kavout danvez gant ur ster tost.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Un doare boutin da stagañ ostilhoù ha mammennoù roadennoù ouzh an arloadoù AI, evit ma c'hallfe an AI o implijout.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperadur (temperature)","text":"Un arventenn a ziviz pegen herder eo respontoù un AI. Izel e ro respontoù stabiloc'h ha diouganusoc'h; uhel e ro respontoù liesseurtoc'h. Hini ebet anezho ne ra dezhañ bezañ reizh bepred.","also":["temperature","model temperature","temperadur"],"noTip":1},{"id":"multimodal","g":"ai","word":"Liesvod (multimodal)","text":"Gouest da labourat gant muioc'h eget ur seurt titouroù, evel testennoù, skeudennoù ha son.","also":["multimodal","multi-modal","liesvod"]},{"id":"evals","g":"ai","word":"Priziadur (eval)","text":"Un test steuñvet evit gouzout pegen mat e ra un AI war skouerioù dibabet, evit gallout keñveriañ modeloù pe promptoù.","also":["evaluation","eval","evals","priziadur"]},{"id":"bias","g":"ai","word":"Gogwiskadur (bias)","text":"Pa stou un AI (pe un den) en un tu en un doare dizereat, alies abalamour d'ar pezh en deus desket diwarnañ.","also":["bias","biased","rakvarn"],"noTip":1},{"id":"responsible","g":"ai","word":"AI atebek","text":"Implijout an AI en un doare just, diarvar hag onest, gant tud a chom atebek eus an disoc'hoù.","also":["responsible AI","ethical AI","AI etikel"]},{"id":"injection","g":"ai","word":"Prompt injection (insinkladur prompt)","text":"Un dro-gamm ma klask urzhioù kuzh en ur bajenn web pe en ur restr lakaat un AI d'ober un dra n'en deus ket goulennet he implijer.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Bevenn feur (rate limit)","text":"Ur vevenn war an niver a c'houlennoù a c'hallit kas d'ur servij e-pad ur prantad termenet. Mar tremenit dreist, e rankit gortoz.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Bevenn implij","text":"Pegement a labour AI a aotre ho steuñvenn e-pad ur prantad; goude-se e ehan pe e koust muioc'h.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Sevel meziantoù dreist-holl en ur zeskrivañ d'un AI ar pezh a fell deoc'h hag en ur lezel anezhañ da skrivañ ar c'hod.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budjed","text":"Ar c'hementad arc'hant lakaet a-gostez evit un dra bennak.","also":["budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Priziadenn ar c'houst","text":"Un divinadenn ar gwellañ eus ar pezh a gousto un dra, a-raok kregiñ.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Distro war ar postadur (ROI)","text":"Ar pezh a zeu deoc'h en-dro e-keñver ar pezh hoc'h eus lakaet. Mar bez pozitivel, e talveze ar boan.","also":["ROI","return on investment","distro war ar postadur"]},{"id":"tco","g":"money","word":"Koust hollek ar berc'hentiezh (TCO)","text":"Kement tra a goust un dra da vat a-hed e vuhez a-bezh, ha n'eo ket hepken e briz prenañ: e lakaat en-dro, ar skoazell, an hizivadennoù hag e lemel kuit erfin.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx ha OpEx","text":"CapEx eo an arc'hant dispignet en a-raok evit traoù a virit; OpEx eo an dispignoù padus, evel ar fakturennoù miziek.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Koumanant","text":"Paeañ en un doare reoliek, miziek pe bloaziek peurliesañ, evit derc'hel da implijout un dra.","also":["subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Meziant e stumm servij (SaaS)","text":"Meziant a implijit enlinenn hag a baeit dre goumanant, tra ma'z eo e saver a ra war-dro e lakaat en-dro evidoc'h.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Paeañ diouzh an implij","text":"Paeañ ar pezh a implijit hepken, evel gant ar jediñ cloud pe an tokenoù AI.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Dreistimplij (overage)","text":"Ar pezh a implijit en tu all d'ar pezh a zo e-barzh ho steuñvenn, ha gallout a ra koustañ ouzhpenn.","also":["overage","overages","overage charges","dreistimplij"]},{"id":"billingalert","g":"money","word":"Galv-diwall fakturenniñ","text":"Ur gemennadenn pa dizh an dispignoù pe an implij ul live hoc'h eus dibabet. Ho kelaouiñ a ra, met ne zalc'h ket atav ar c'houstoù ouzhpenn.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Live digoust (free tier)","text":"Ul live digoust eus ur servij paeüs, gant bevennoù. Mat evit kregiñ.","also":["free tier","free plan"]},{"id":"pricing","g":"money","word":"Steuñvenn prizioù","text":"Ar pakadoù disheñvel a werzh ur servij, pep hini gant e briz hag e vevennoù.","also":["pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Lañvaz (licence)","text":"Ar reolennoù a lavar penaos e c'hallit implijout, eilañ, kemmañ pe rannañ un dra savet gant unan all, evel meziantoù, fontoù pe skeudennoù.","also":["licence","licences","license","licenses","lañvazioù"],"noTip":1},{"id":"opensource","g":"money","word":"Mammenn digor (open source)","text":"Meziant ma c'hall an holl lenn e god, e implijout hag alies e gemmañ evit netra, hervez reolennoù e lañvaz.","also":["open source","open-source","open source software","OSS","meziant frank"]},{"id":"osslicence","g":"money","word":"Lañvaz mammenn digor","text":"Ar reolennoù a zeu gant ar c'hod mammenn digor. Lod a ro an tu deoc'h d'ober kazi pep tra (evel MIT); lod all a c'houlenn ouzhoc'h rannañ ho kemmoù ivez (evel GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Perc'hennel (proprietary)","text":"Dalc'het gant un embregerezh ha n'eo ket dieub da eilañ pe da gemmañ. Ar c'hontrol eus mammenn digor.","also":["proprietary","proprietary software","meziant perc'hennel"]},{"id":"copyright","g":"money","word":"Gwir an aozer","text":"Gwir lezennel ur c'hrouer da reoliñ an eilskridoù eus e labour, kod ha skridoù en o zouez.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Perc'hentiezh speredel (IP)","text":"Ideennoù ha krouidigezhioù a vez sellet gant al lezenn evel madoù, evel kod, tresoù, anvioù ha logoioù.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Divizoù implijout","text":"Ar reolennoù a asantit dezho pa implijit ur servij.","also":["terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Kevrat","text":"Un emglev skrivet etre daou du, kreñvaet gant al lezenn.","also":["contract","contracts","kevratoù"],"noTip":1},{"id":"sow","g":"money","word":"Displegadur al labour (SOW)","text":"Un teul a lavar resis peseurt labour a vo graet, betek pegoulz hag evit pegement.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Priz divoug","text":"Ur priz emglevet evit al labour a-bezh, pegeit bennak e pado.","also":["fixed price","fixed-price","priz divoug"]},{"id":"tm","g":"money","word":"Amzer ha danvez (T&M)","text":"Paeañ an eurioù labouret da vat hag an traoù implijet da vat, e-lec'h ur priz divoug.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Fakturenn","text":"Ur gont a c'houlenn ur paeamant evit ul labour graet pe marc'hadourezh pourchaset.","also":["invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Stag ouzh ur pourvezer (vendor lock-in)","text":"Pa'z eo ken diaes pe ken ker kuitaat ur pourvezer ma chomit stag outañ.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Prenadurioù (procurement)","text":"An argerzh evit dibab pourvezerien ha prenañ diganto.","also":["procurement","prenadurioù"]},{"id":"servicecredit","g":"money","word":"Kred servij (service credit)","text":"Arc'hant distaolet pe ur distaol a resevit pa ne zouj ket ur pourvezer d'e SLA.","also":["service credit","service credits"]}]}};
